import React, { useState, useEffect } from 'react';
import Swal from 'sweetalert2';
import Navigation from '../Navigation';

const difficultySettings = {
  easy: { tubes: 4, colors: 3, score: 5 },
  medium: { tubes: 5, colors: 4, score: 10 },
  hard: { tubes: 6, colors: 5, score: 15 }
};

const pastelColors = [
  'rgba(255, 105, 180, 1)',
  'rgba(70, 130, 255, 1)',
  'rgba(255, 220, 60, 1)',
  'rgba(50, 205, 50, 1)',
  'rgba(147, 112, 219, 1)',
];

const generateTubes = (settings) => {
  const tubes = [];
  const totalLiquids = pastelColors
    .slice(0, settings.colors)
    .flatMap(color => Array(5).fill(color));
  
  for (let i = totalLiquids.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [totalLiquids[i], totalLiquids[j]] = [totalLiquids[j], totalLiquids[i]];
  }

  for (let i = 0; i < settings.tubes; i++) {
    tubes.push(totalLiquids.splice(0, 5));
  }

  return [...tubes, []];
};

const Water = () => {
  const [difficulty, setDifficulty] = useState('easy');
  const [tubes, setTubes] = useState(generateTubes(difficultySettings[difficulty]));
  const [selectedTube, setSelectedTube] = useState(null);
  const [score, setScore] = useState(0);
  const [filledTubes, setFilledTubes] = useState([]);
  const [showInstructions, setShowInstructions] = useState(false);

  useEffect(() => {
    showIntroStory();
  }, []);

  const showIntroStory = async () => {
    await Swal.fire({
      title: '🔮 Emergency at the Magic Potion Lab! 🔮',
      html: `
        <p>The apprentice wizard accidentally mixed up all the magical potions!</p>
        <p>We need your help to sort them back into their proper vials before the Archmage returns.</p>
        <p>Can you help restore order to the Potion Laboratory?</p>
      `,
      icon: 'warning',
      timerProgressBar: true,
      showConfirmButton: true,
      confirmButtonText: '🪄 I\'ll Help!',
      position: 'center',
      background: '#fff3e0',
      confirmButtonColor: '#7e57c2'
    });
  };

  const checkForValidMoves = () => {
    for (let i = 0; i < tubes.length; i++) {
      for (let j = 0; j < tubes.length; j++) {
        if (i !== j && tubes[i].length > 0 && 
            (tubes[j].length === 0 || 
             (tubes[j].length < 5 && 
              tubes[j][tubes[j].length - 1] === tubes[i][tubes[i].length - 1]))) {
          return true;
        }
      }
    }
    return false;
  };

  const handleDifficultyChange = (newDifficulty) => {
    setDifficulty(newDifficulty);
    setTubes(generateTubes(difficultySettings[newDifficulty]));
    setSelectedTube(null);
    setScore(0);
    setFilledTubes([]);
  };

  const handleTubeClick = (index) => {
    if (selectedTube === null) {
      if (tubes[index].length > 0) {
        setSelectedTube(index);
      }
    } else {
      const targetTube = tubes[index];
      const sourceTube = tubes[selectedTube];
      
      if (selectedTube === index) {
        setSelectedTube(null);
        return;
      }

      if (targetTube.length >= 5) {
        Swal.fire({
          title: '⚠️ Invalid Move ⚠️',
          text: 'Target tube is already full!',
          icon: 'error',
          timer: 1500,
          showConfirmButton: false
        });
        setSelectedTube(null);
        return;
      }

      if (targetTube.length > 0 && targetTube[targetTube.length - 1] !== sourceTube[sourceTube.length - 1]) {
        Swal.fire({
          title: '⚠️ Invalid Move ⚠️',
          text: 'Colors must match!',
          icon: 'error',
          timer: 1500,
          showConfirmButton: false
        });
        setSelectedTube(null);
        return;
      }

      const liquidToPour = sourceTube.pop();
      const newTubes = [...tubes];
      newTubes[index].push(liquidToPour);
      
      let newScore = score;
      if (newTubes[index].length === 5 && newTubes[index].every(color => color === newTubes[index][0])) {
        newScore = score + difficultySettings[difficulty].score;
        setScore(newScore);
        setFilledTubes([...filledTubes, index]);
      }
      
      setTubes(newTubes);
      setSelectedTube(null);

      const nonEmptyTubes = newTubes.filter(tube => tube.length > 0);
      const allTubesSorted = nonEmptyTubes.every(tube => 
        tube.length === 5 && tube.every(color => color === tube[0])
      );
      const hasValidMoves = checkForValidMoves();

      if (allTubesSorted) {
        const finalScore = newScore;
        setTimeout(() => {
          showGameEndAlert(true, finalScore);
        }, 100);
      } else if (!hasValidMoves && nonEmptyTubes.length > 0) {
        const finalScore = newScore;
        setTimeout(() => {
          showGameEndAlert(false, finalScore);
        }, 100);
      }
    }
  };

  const showGameEndAlert = (isVictory, finalScore) => {
    if (isVictory) {
      Swal.fire({
        title: '✨ Magical Success! 🌟',
        html: `
          <p>Outstanding work, Master Potion Sorter!</p>
          <p>You've successfully reorganized all the magical potions.</p>
          <p>The Archmage will be most pleased!</p>
          <p>Final Score: <strong>${finalScore} points </strong></p>
        `,
        icon: 'success',
        confirmButtonText: '🏰 Return to the Academy',
        background: '#e8f5e9',
        confirmButtonColor: '#4caf50'
      }).then((result) => {
        if (result.isConfirmed) {
          window.location.href='/';
        }
      });
    } else {
      Swal.fire({
        title: '💥 Magical Mishap! 🌪️',
        html: `
          <p>Oh dear! The potions are stuck in an impossible configuration.</p>
          <p>Don't worry, these things happen to the best of wizards.</p>
          <p>Why not try again with a fresh set of potions next time?</p>
          <p>Final Score: <strong>${finalScore} points </strong></p>
        `,
        icon: 'error',
        confirmButtonText: '🏰 Return to the Academy',
        background: '#fbe9e7',
        confirmButtonColor: '#ff5722'
      }).then((result) => {
        if (result.isConfirmed) {
          window.location.href='/';
        }
      });
    }
  };

  return (
    <div className="min-h-screen w-full bg-gradient-to-br from-violet-200 via-pink-200 to-yellow-200 relative overflow-hidden">
      <div className="absolute inset-0">
        <div className="absolute top-0 left-0 w-72 h-72 bg-pink-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-tl"></div>
        <div className="absolute top-0 right-0 w-72 h-72 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-tr"></div>
        <div className="absolute bottom-0 left-0 w-72 h-72 bg-blue-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-bl"></div>
        <div className="absolute bottom-0 right-0 w-72 h-72 bg-green-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-br"></div>
        <div className="absolute left-1/2 -translate-x-1/2 top-1/2 -translate-y-1/2 w-96 h-96 bg-yellow-300 rounded-full mix-blend-multiply filter blur-xl opacity-50 animate-pulse"></div>
      </div>

      <div className="relative min-h-screen flex items-center justify-center p-4">
        <div className="w-full max-w-4xl bg-white/80 backdrop-blur-md rounded-xl shadow-2xl p-8" style={{border: '3px solid black'}}>
          <div className="text-center mb-8">
            <div className="flex justify-center items-center gap-4 mb-6">
              <h1 className="text-3xl font-bold text-black">Water Sort Puzzle</h1>
              <button onClick={() => setShowInstructions(true)} className="p-2 text-2xl hover:bg-indigo-100 rounded">
                ℹ️
              </button>
            </div>
            <div className="text-xl font-semibold text-black mb-4">
              Score: {score}
            </div>
            <div className="flex justify-center gap-4 mb-6">
              {Object.keys(difficultySettings).map((level) => (
                <button
                  key={level}
                  onClick={() => handleDifficultyChange(level)}
                  className={`px-4 py-2 rounded-lg text-white transition-colors ${
                    difficulty === level 
                    ? 'bg-indigo-600' 
                    : 'bg-indigo-400 hover:bg-indigo-500'
                  }`}
                >
                  {level.charAt(0).toUpperCase() + level.slice(1)}
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-wrap justify-center gap-6">
            {tubes.map((tube, index) => (
              <div
                key={index}
                onClick={() => handleTubeClick(index)}
                className={`w-16 md:w-20 h-48 md:h-56 bg-gray-100 rounded-b-3xl rounded-t-lg overflow-hidden cursor-pointer transition-transform ${
                  selectedTube === index ? 'scale-110' : ''
                } ${filledTubes.includes(index) ? 'border-green-500' : ''}`}
                style={{
                  border: '3px solid black',
                  boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                  transform: selectedTube === index ? 'scale(1.1)' : 'scale(1)',
                  transition: 'transform 0.3s ease'
                }}
              >
                <div className="h-full flex flex-col-reverse">
                  {tube.map((color, idx) => (
                    <div
                      key={idx}
                      className="h-1/5 transition-all"
                      style={{ 
                        backgroundColor: color,
                        transition: 'background-color 0.3s ease'
                      }}
                    />
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {showInstructions && (
        <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm">
          <div className="bg-white p-8 rounded-2xl max-w-[500px] w-[90%]">
            <h2 className="text-2xl mb-5 text-indigo-900 text-center font-bold">
              How to Play
            </h2>
            <div className="flex items-center gap-2.5 mb-4">
              <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">1</span>
              <p className="text-gray-700">Choose a difficulty level to start the game. Each level has different numbers of tubes and colors.</p>
            </div>
            <div className="flex items-center gap-2.5 mb-4">
              <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">2</span>
              <p className="text-gray-700">Click a tube to select it, then click another tube to pour the liquid. The liquid can only be poured into empty tubes or tubes with matching colors on top.</p>
            </div>
            <div className="flex items-center gap-2.5 mb-4">
              <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">3</span>
              <p className="text-gray-700">Fill tubes with matching colors to score points. Points awarded vary by difficulty: Easy (+5), Medium (+10), Hard (+15).</p>
            </div>
            <button
              onClick={() => setShowInstructions(false)}
              className="w-full h-12 bg-indigo-900 text-white text-base font-semibold rounded-lg cursor-pointer flex justify-center items-center mt-8 transition-all duration-300 hover:bg-indigo-800"
            >
              Close
            </button>
          </div>
        </div>
      )}

      <style jsx>{`
        @keyframes blob-tl {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(calc(100vw - 18rem), 0) scale(1.1); }
          50% { transform: translate(calc(100vw - 18rem), calc(100vh - 18rem)) scale(1); }
          75% { transform: translate(0, calc(100vh - 18rem)) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-tr {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(0, calc(100vh - 18rem)) scale(1.1); }
          50% { transform: translate(calc(-100vw + 18rem), calc(100vh - 18rem)) scale(1); }
          75% { transform: translate(calc(-100vw + 18rem), 0) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-br {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(calc(-100vw + 18rem), 0) scale(1.1); }
          50% { transform: translate(calc(-100vw + 18rem), calc(-100vh + 18rem)) scale(1); }
          75% { transform: translate(0, calc(-100vh + 18rem)) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-bl {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(0, calc(-100vh + 18rem)) scale(1.1); }
          50% { transform: translate(calc(100vw - 18rem), calc(-100vh + 18rem)) scale(1); }
          75% { transform: translate(calc(100vw - 18rem), 0) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        .animate-blob-tl {
          animation: blob-tl 20s linear infinite;
        }
        
        .animate-blob-tr {
          animation: blob-tr 20s linear infinite;
        }
        
        .animate-blob-bl {
          animation: blob-bl 20s linear infinite;
        }
        
        .animate-blob-br {
          animation: blob-br 20s linear infinite;
        }
        
        .animate-pulse {
          animation: pulse 10s infinite;
        }
        
        @keyframes pulse {
          0%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0.5; }
          50% { transform: translate(-50%, -50%) scale(1.2); opacity: 0.3; }
        }
      `}</style>
      <Navigation currentPage="stack-game" />
    </div>
  );
};

export default Water;