import React, { useState } from 'react';
import { Check, AlertCircle, Star } from 'lucide-react';

const StarRating = ({ rating, setRating }) => {
  const stars = [1, 2, 3, 4, 5];
  return (
    <div className="w-full p-3 rounded-lg border border-gray-300 bg-white">
      <div className="flex items-center gap-1">
        {stars.map((star) => (
          <button
            key={star}
            type="button"
            onClick={() => setRating(star)}
            className="focus:outline-none transition-colors"
          >
            <Star
              className={`w-8 h-8 ${
                star <= rating
                  ? 'fill-yellow-400 text-yellow-400'
                  : 'fill-gray-200 text-gray-200'
              } hover:fill-yellow-400 hover:text-yellow-400 transition-colors`}
            />
          </button>
        ))}
      </div>
    </div>
  );
};

const FeedbackForm = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    rating: 5,
    category: 'general',
    feedback: '',
  });

  const [errors, setErrors] = useState({});
  const [submitStatus, setSubmitStatus] = useState({ type: '', message: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const setRating = (value) => {
    setFormData((prev) => ({
      ...prev,
      rating: value,
    }));
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email';
    }

    if (!formData.feedback.trim()) {
      newErrors.feedback = 'Feedback is required';
    } else if (formData.feedback.length < 10) {
      newErrors.feedback = 'Feedback must be at least 10 characters long';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);

    try {
      const scriptURL =
        'https://script.google.com/macros/s/AKfycbwj7X8QzVvJl0mZiX2pNnn2mF3XepgbhUGi-QarARUhWcES-EBRdgOt_aD6MQ2-TZZ3/exec';
      const feedbackData = {
        ...formData,
        createdAt: new Date().toISOString(),
      };

      const response = await fetch(scriptURL, {
        method: 'POST',
        mode: 'no-cors',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(feedbackData),
      });

      setSubmitStatus({
        type: 'success',
        message: 'Feedback submitted successfully!',
      });

      // Reset form fields after submission
      setFormData({
        name: '',
        email: '',
        rating: 5,
        category: 'general',
        feedback: '',
      });

      // Automatically hide success message after 5 seconds
      setTimeout(() => {
        setSubmitStatus({ type: '', message: '' });
      }, 5000);
    } catch (error) {
      console.error('Error submitting feedback:', error);
      setSubmitStatus({
        type: 'error',
        message: 'Failed to submit feedback. Please try again.',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
    if (errors[name]) {
      setErrors((prev) => ({
        ...prev,
        [name]: '',
      }));
    }
  };

  return (
    <div className="container mx-auto px-4 py-16 bg-white">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col lg:flex-row gap-20 items-center lg:items-start">
          <div className="w-full lg:w-1/3 lg:sticky lg:max-w-xs">
            <h2 className="text-4xl font-bold text-navy mb-6">
              Your Feedback Matters
            </h2>
            <div className="space-y-6 text-lg text-gray-700">
              <p>
                We're committed to providing the best learning experience for
                our users. Your feedback helps us understand what works well
                and where we can improve.
              </p>
              <p>
                 Whether it's about our course content, user interface, or overall experience,
                 we value every piece of feedback we receive.
               </p>
               <div className="bg-blue-100 p-6 rounded-lg">
                 <h3 className="text-xl font-semibold text-blue-900 mb-3">Why Share Feedback?</h3>
                 <ul className="space-y-2 text-blue-800">
                   <li>• Help improve the learning experience</li>
                   <li>• Shape future content and features</li>
                   <li>• Contribute to our community's growth</li>
                   <li>• Report any issues or suggestions</li>
                 </ul>
               </div>
            </div>
          </div>

          <div className="w-full lg:w-2/3 bg-white rounded-2xl shadow-lg p-8 mt-5">
            {submitStatus.message && (
              <div
                className={`mb-6 p-4 rounded-lg flex items-center gap-2 ${
                  submitStatus.type === 'success'
                    ? 'bg-green-100 text-green-800'
                    : 'bg-red-100 text-red-800'
                }`}
              >
                <p className="font-medium">{submitStatus.message}</p>
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Form fields */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Name */}
                <div className="space-y-2">
                  <label className="block text-gray-700 font-medium">
                    Full Name
                  </label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    placeholder="Enter your name"
                    className={`w-full p-3 rounded-lg border ${
                      errors.name ? 'border-red-500' : 'border-gray-300'
                    }`}
                  />
                  {errors.name && (
                    <p className="text-red-500 text-sm mt-1">{errors.name}</p>
                  )}
                </div>
                {/* Email */}
                <div className="space-y-2">
                  <label className="block text-gray-700 font-medium">
                    Email Address
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    placeholder="Enter your email"
                    className={`w-full p-3 rounded-lg border ${
                      errors.email ? 'border-red-500' : 'border-gray-300'
                    }`}
                  />
                  {errors.email && (
                    <p className="text-red-500 text-sm mt-1">{errors.email}</p>
                  )}
                </div>
              </div>

              {/* Rating */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="block text-gray-700 font-medium">Rating</label>
                  <StarRating rating={formData.rating} setRating={setRating} />
                </div>
                {/* Category */}
                <div className="space-y-2">
                  <label className="block text-gray-700 font-medium">
                    Feedback Category
                  </label>
                  <select
                    name="category"
                    value={formData.category}
                    onChange={handleInputChange}
                    className="w-full p-3 rounded-lg border border-gray-300 bg-white"
                  >
                    <option value="general">General Feedback</option>
                    <option value="content">Course Content</option>
                    <option value="ui">User Interface</option>
                    <option value="bugs">Bug Report</option>
                    <option value="suggestion">Suggestion</option>
                  </select>
                </div>
              </div>

              {/* Feedback */}
              <div className="space-y-2">
                <label className="block text-gray-700 font-medium">
                  Your Feedback
                </label>
                <textarea
                  name="feedback"
                  value={formData.feedback}
                  onChange={handleInputChange}
                  placeholder="Share your thoughts, suggestions, or report issues..."
                  rows="6"
                  className={`w-full p-4 rounded-lg border ${
                    errors.feedback ? 'border-red-500' : 'border-gray-300'
                  }`}
                ></textarea>
                {errors.feedback && (
                  <p className="text-red-500 text-sm mt-1">{errors.feedback}</p>
                )}
              </div>

              {/* Submit button */}
              <button
                type="submit"
                disabled={isSubmitting}
                className={`w-full py-4 bg-blue-800 text-white rounded-lg transition-colors font-medium text-lg ${
                  isSubmitting ? 'opacity-75 cursor-not-allowed' : 'hover:bg-blue-900'
                }`}
              >
                {isSubmitting ? 'Submitting...' : 'Submit Feedback'}
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FeedbackForm;