import React, { useState } from 'react';
import { Menu, X, LayoutGrid, List } from 'lucide-react';
import Bst from './../Images/bst.jpg';
import Linkedlist from './../Images/ll.jpg';

const NavLink = ({ to, active, children }) => {
  return (
    <a
      to={to}
      className={`font-sans px-4 py-2 rounded-lg transition-all duration-300 ${
        active 
          ? 'bg-blue-500 text-white hover:bg-blue-600' 
          : 'bg-white text-black hover:bg-blue-100'
      }`}
    >
      {children}
    </a>
  );
};

const BoxCard = ({ imgSrc, title, description, learnMoreLink }) => {
    return (
      <div className="w-full max-w-sm bg-white rounded-lg shadow-lg overflow-hidden transform transition duration-300 hover:scale-105">
        <div className="w-full h-75">
          <img 
            src={imgSrc} 
            alt={title} 
            className="block w-full h-[350px] object-center" 
          />
        </div>
        <div className="p-4">
          <h3 className="text-xl font-bold mb-2">{title}</h3>
          <p className="text-gray-600 mb-4">{description}</p>
          <a 
            href={learnMoreLink}
            className="inline-block px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors"
          >
            Learn More
          </a>
        </div>
      </div>
    );
};

const ListItem = ({ title, description, learnMoreLink }) => {
  return (
    <div className="w-full bg-white rounded-lg shadow-lg p-4 mb-4 transform transition duration-300 hover:scale-105">
      <div className="flex justify-between items-start">
        <div>
          <h3 className="text-xl font-bold mb-2">{title}</h3>
          <p className="text-gray-600">{description}</p>
        </div>
        <a 
          href={learnMoreLink}
          className="inline-block px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors"
        >
          Learn More
        </a>
      </div>
    </div>
  );
};

const AlgorithmsPage = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [viewType, setViewType] = useState('box'); 

  const algorithms = [
    {
      imgSrc: Linkedlist,
      title: "Linked List",
      description: "A linear data structure where elements are stored in nodes, and each node points to the next node in the sequence.",
      learnMoreLink: "/llalgo"
    },
    {
      imgSrc: Bst,
      title: "Binary Search Tree",
      description: "A tree data structure where each node has at most two children, with left nodes smaller and right nodes larger than the parent.",
      learnMoreLink: "/bstalgo"
    }
  ];

  return (
    <div className="min-h-screen bg-gray-100 font-sans">
      <nav className="bg-[#000080] p-4 relative z-50">
        <div className="container mx-auto flex justify-between items-center">
          <a href="/" className="text-2xl font-bold text-white">
            ALGORIFIC
          </a>
          
          <div className="md:hidden">
            <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="text-white">
              {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>

          <div className={`${isMenuOpen ? 'flex' : 'hidden'} md:flex flex-col md:flex-row absolute md:relative top-full left-0 right-0 md:top-auto bg-[#000080] md:bg-transparent p-4 md:p-0 space-y-2 md:space-y-0 md:space-x-4 z-50`}>
            <NavLink to="/">Learn</NavLink>
            <NavLink to="/algohome" active>Algorithm</NavLink>
          </div>
        </div>
      </nav>

      <div className="container mx-auto px-4 py-8">
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold">Algorithms</h1>
          <div className="flex space-x-4">
            <button 
              onClick={() => setViewType('box')}
              className={`p-2 rounded ${viewType === 'box' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
            >
              <LayoutGrid size={24} />
            </button>
            <button 
              onClick={() => setViewType('list')}
              className={`p-2 rounded ${viewType === 'list' ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
            >
              <List size={24} />
            </button>
          </div>
        </div>

        {viewType === 'box' ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {algorithms.map((algo, index) => (
              <BoxCard key={index} {...algo} />
            ))}
          </div>
        ) : (
          <div className="space-y-4">
            {algorithms.map((algo, index) => (
              <ListItem key={index} {...algo} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default AlgorithmsPage;