import { color } from "framer-motion";
import React, { useState, useEffect } from "react";

const bstOperations = {
  insert: [
    {
      lines: [
        "function insert(node, value) {",
        "    if (node == null) {",
        "        return newNode(value);",
        "    }"
      ],
      condition: (node, value) => node === null,
      description: "Creating new node"
    },
    {
      lines: [
        "    if (value < node.value) {",
        "        node.left = insert(node.left, value);",
        "    }"
      ],
      condition: (node, value) => value < node.value,
      description: "Moving to left subtree"
    },
    {
      lines: [
        "    } else if (value > node.value) {",
        "        node.right = insert(node.right, value);",
        "    }"
      ],
      condition: (node, value) => value > node.value,
      description: "Moving to right subtree"
    },
    {
      lines: [
        "    return node;",
        "}"
      ],
      condition: (node, value) => value === node.value,
      description: "Node already exists"
    }
  ],
  delete: [
    {
      lines: [
        "function deleteNode(node, value) {",
        "    if (node == null) return null;"
      ],
      condition: (node, value) => node === null,
      description: "Node not found"
    },
    {
      lines: [
        "    if (value < node.value) {",
        "        node.left = deleteNode(node.left, value);",
        "    }"
      ],
      condition: (node, value) => value < node.value,
      description: "Moving to left subtree"
    },
    {
      lines: [
        "    } else if (value > node.value) {",
        "        node.right = deleteNode(node.right, value);",
        "    }"
      ],
      condition: (node, value) => value > node.value,
      description: "Moving to right subtree"
    },
    {
      lines: [
        "    } else {",
        "        if (node.left == null) return node.right;",
        "        if (node.right == null) return node.left;"
      ],
      condition: (node, value) => value === node.value && (!node.left || !node.right),
      description: "Deleting node with one or no children"
    },
    {
      lines: [
        "        let minNode = findMin(node.right);",
        "        node.value = minNode.value;",
        "        node.right = deleteNode(node.right, minNode.value);"
      ],
      condition: (node, value) => value === node.value && node.left && node.right,
      description: "Deleting node with two children"
    }
  ]
};

const initialTree = {
  value: 50,
  left: { value: 30, left: { value: 20, left: null, right: null }, right: { value: 40, left: null, right: null } },
  right: { value: 70, left: { value: 60, left: null, right: null }, right: { value: 80, left: null, right: null } }
};

const TreeLine = ({ x1, y1, x2, y2 }) => (
  <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="#000" strokeWidth="2" />
);

const TreeNode = ({ value, isHighlighted, isTraversed }) => (
  <g>
    <circle 
      r="20" 
      fill={isHighlighted ? "#ff4444" : isTraversed ? "#ffeb3b" : "#3498db"} 
      stroke="#000" 
      strokeWidth="4" 
    />
    <text 
      fill="white" 
      textAnchor="middle" 
      dominantBaseline="central" 
      fontSize="14" 
      fontWeight="bold"
    >
      {value}
    </text>
  </g>
);

const BSTApp = () => {
  const [tree, setTree] = useState(initialTree);
  const [currentNode, setCurrentNode] = useState(null);
  const [traversedNodes, setTraversedNodes] = useState(new Set());
  const [inputValue, setInputValue] = useState("");
  const [operation, setOperation] = useState("insert");
  const [currentLine, setCurrentLine] = useState(-1);
  const [explanation, setExplanation] = useState("Enter a value and select an operation");
  const [isExecuting, setIsExecuting] = useState(false);

  const calculateNodePosition = (node, x, y, level, width) => {
    if (!node) return null;
    const newWidth = width / 2;
    const yOffset = 80;
    const leftChild = calculateNodePosition(node.left, x - newWidth, y + yOffset, level + 1, newWidth);
    const rightChild = calculateNodePosition(node.right, x + newWidth, y + yOffset, level + 1, newWidth);
    return { ...node, x, y, children: { left: leftChild, right: rightChild } };
  };

  const renderConnections = (node) => {
    if (!node) return null;
    const connections = [];
    if (node.children.left) {
      connections.push(
        <TreeLine 
          key={`${node.value}-${node.children.left.value}`} 
          x1={node.x} 
          y1={node.y} 
          x2={node.children.left.x} 
          y2={node.children.left.y} 
        />
      );
    }
    if (node.children.right) {
      connections.push(
        <TreeLine 
          key={`${node.value}-${node.children.right.value}`} 
          x1={node.x} 
          y1={node.y} 
          x2={node.children.right.x} 
          y2={node.children.right.y} 
        />
      );
    }
    return [
      ...connections,
      node.children.left && renderConnections(node.children.left),
      node.children.right && renderConnections(node.children.right)
    ];
  };

  const renderNodes = (node) => {
    if (!node) return null;
    return (
      <>
        <g transform={`translate(${node.x},${node.y})`}>
          <TreeNode 
            value={node.value} 
            isHighlighted={currentNode && currentNode.value === node.value}
            isTraversed={traversedNodes.has(node.value)}
          />
        </g>
        {node.children.left && renderNodes(node.children.left)}
        {node.children.right && renderNodes(node.children.right)}
      </>
    );
  };

  const insertNode = (node, value) => {
    if (node == null) {
      return { value, left: null, right: null };
    }
    if (value < node.value) {
      return { ...node, left: insertNode(node.left, value) };
    } else if (value > node.value) {
      return { ...node, right: insertNode(node.right, value) };
    }
    return node;
  };

  const findMin = (node) => {
    while (node.left != null) {
      node = node.left;
    }
    return node;
  };

  const deleteNode = (node, value) => {
    if (node == null) return null;
    if (value < node.value) {
      return { ...node, left: deleteNode(node.left, value) };
    } else if (value > node.value) {
      return { ...node, right: deleteNode(node.right, value) };
    } else {
      if (node.left == null) return node.right;
      if (node.right == null) return node.left;
      const minNode = findMin(node.right);
      return {
        ...node,
        value: minNode.value,
        right: deleteNode(node.right, minNode.value)
      };
    }
  };

  const [activeCodeBlock, setActiveCodeBlock] = useState(null);

  const executeStep = async () => {
    if (!isExecuting) return;

    const value = parseInt(inputValue);
    if (!currentNode) {
      setCurrentNode(tree);
      setTraversedNodes(new Set());
      return;
    }

    setTraversedNodes(prev => new Set([...prev, currentNode.value]));

    const operations = bstOperations[operation];
    let activeBlock = null;

    if (operation === "insert") {
      if (currentNode === null) {
        activeBlock = 0; // New node creation
      } else if (value < currentNode.value) {
        activeBlock = 1; // Left subtree
        if (currentNode.left === null) {
          setTree(prevTree => insertNode(prevTree, value));
          setIsExecuting(false);
          setCurrentNode(null);
        } else {
          setCurrentNode(currentNode.left);
        }
      } else if (value > currentNode.value) {
        activeBlock = 2; // Right subtree
        if (currentNode.right === null) {
          setTree(prevTree => insertNode(prevTree, value));
          setIsExecuting(false);
          setCurrentNode(null);
        } else {
          setCurrentNode(currentNode.right);
        }
      } else {
        activeBlock = 3; // Node exists
        setIsExecuting(false);
        setCurrentNode(null);
      }
    } else if (operation === "delete") {
      // Similar logic for delete operation...
      if (currentNode === null) {
        activeBlock = 0;
      } else if (value < currentNode.value) {
        activeBlock = 1;
        if (currentNode.left === null) {
          setIsExecuting(false);
          setCurrentNode(null);
        } else {
          setCurrentNode(currentNode.left);
        }
      } else if (value > currentNode.value) {
        activeBlock = 2;
        if (currentNode.right === null) {
          setIsExecuting(false);
          setCurrentNode(null);
        } else {
          setCurrentNode(currentNode.right);
        }
      } else {
        activeBlock = currentNode.left && currentNode.right ? 4 : 3;
        setTree(prevTree => deleteNode(prevTree, value));
        setIsExecuting(false);
        setCurrentNode(null);
      }
    }

    setActiveCodeBlock(activeBlock);
    setExplanation(operations[activeBlock].description);
  };


  useEffect(() => {
    const timer = setInterval(() => {
      if (isExecuting) {
        executeStep();
      }
    }, 1000);

    return () => clearInterval(timer);
  }, [isExecuting, currentNode]);

  const handleExecute = () => {
    if (!inputValue || isNaN(parseInt(inputValue))) {
      setExplanation("Please enter a valid number");
      return;
    }
    setIsExecuting(true);
  };

  const positionedTree = calculateNodePosition(tree, 300, 50, 0, 300);

  const inputStyles = {
    width: '120px',
    padding: '8px',
    border: '1px solid #ccc',
    color: 'black',
    borderRadius: '4px',
    marginRight: '8px'
  };

  const selectStyles = {
    padding: '8px',
    border: '1px solid #ccc',
    borderRadius: '4px',
    color: 'black',
    marginRight: '8px'
  };

  const buttonStyles = {
    padding: '8px 16px',
    backgroundColor: '#3498db',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    opacity: isExecuting ? '0.5' : '1'
  };

  const controlsContainerStyles = {
    display: 'flex',
    alignItems: 'center',
    marginBottom: '24px'
  };

  return (
    <div style={{ 
      display: 'flex', 
      alignItems: 'center', 
      justifyContent: 'space-between', 
      gap: '40px',
      minHeight: '100vh',
      backgroundColor: '#f0f4f8',
      padding: '16px'
    }}>
      <div style={{
        flex: 1,
        minHeight: '85vh',
        padding: '24px',
        backgroundColor: 'white',
        borderRadius: '8px',
        boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)'
      }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '16px', color:'black' }}>
          Binary Search Tree Visualization
        </h1>
        <div style={controlsContainerStyles}>
          <input
            type="number"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            style={inputStyles}
            placeholder="Enter value"
          />
          <select
            value={operation}
            onChange={(e) => setOperation(e.target.value)}
            style={selectStyles}
          >
            <option value="insert" style={{color:'black'}}>Insert</option>
            <option value="delete" style={{color:'black'}}>Delete</option>
          </select>
          <button
            onClick={handleExecute}
            disabled={isExecuting}
            style={buttonStyles}
          >
            Execute
          </button>
        </div>
        <p style={{ color: '#666', marginBottom: '16px' }}>{explanation}</p>
        <div style={{ width: '100%', overflow: 'hidden' }}>
          <svg 
            width="600" 
            height="400" 
            style={{
              width: '100%',
              backgroundColor: 'white',
              borderRadius: '8px'
            }}
            viewBox="0 0 600 400"
            preserveAspectRatio="xMidYMid meet"
          >
            {positionedTree && (
              <>
                {renderConnections(positionedTree)}
                {renderNodes(positionedTree)}
              </>
            )}
          </svg>
        </div>
      </div>
      <div style={{
        flex: 1,
        minHeight: '85vh',
        padding: '24px',
        backgroundColor: 'white',
        borderRadius: '8px',
        boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)'
      }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '16px', color:'black' }}>
          BST {operation.charAt(0).toUpperCase() + operation.slice(1)} Algorithm
        </h1>
        <div style={{ 
          backgroundColor: '#f8f8f8', 
          padding: '16px', 
          borderRadius: '8px',
          overflowY: 'auto',
          maxHeight: 'calc(85vh - 100px)'
        }}>
          {bstOperations[operation].map((block, blockIndex) => (
            <div key={blockIndex}>
              {block.lines.map((line, lineIndex) => (
                <div
                  key={`${blockIndex}-${lineIndex}`}
                  style={{
                    color: 'black',
                    fontFamily: 'monospace',
                    padding: '8px',
                    backgroundColor: activeCodeBlock === blockIndex ? '#fff3cd' : 'transparent'
                  }}
                >
                  {line}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default BSTApp;