import React, { useState, useRef } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import Navigation from "../Navigation";

const StackVisualization = () => {
  const [stack, setStack] = useState([]);
  const [maxSize, setMaxSize] = useState(5);
  const [inputValue, setInputValue] = useState("");
  const [message, setMessage] = useState("");
  const [selectedLanguage, setSelectedLanguage] = useState("pseudo");
  const [activeSection, setActiveSection] = useState("learn");
  const [activeLearningPage, setActiveLearningPage] = useState(1);
  const [showHowToUseModal, setShowHowToUseModal] = useState(false);
  const inputRef = useRef(null);

  const codeExamples = {
    pseudo: `Stack Operations Pseudocode:

push(element):
  if stack is full:
    return overflow
  increment top
  stack[top] = element
  return success

pop():
  if stack is empty:
    return underflow
  element = stack[top]
  decrement top
  return element`,

    cpp: `<span style="color: #FF79C6">template</span> <span style="color: #BD93F9">&lt;</span><span style="color: #FF79C6">typename</span> <span style="color: #50FA7B">T</span><span style="color: #BD93F9">&gt;</span>
<span style="color: #FF79C6">class</span> <span style="color: #50FA7B">Stack</span> {
<span style="color: #FF79C6">private</span>:
    <span style="color: #50FA7B">T</span>* arr;
    <span style="color: #FF79C6">int</span> top, size;
    
<span style="color: #FF79C6">public</span>:
    <span style="color: #50FA7B">Stack</span>(<span style="color: #FF79C6">int</span> s) {
        top = -<span style="color: #BD93F9">1</span>;
        size = s;
        arr = <span style="color: #FF79C6">new</span> <span style="color: #50FA7B">T</span>[s];
    }
    
    <span style="color: #FF79C6">void</span> <span style="color: #50FA7B">push</span>(<span style="color: #50FA7B">T</span> x) {
        <span style="color: #FF79C6">if</span> (top >= size-<span style="color: #BD93F9">1</span>) <span style="color: #FF79C6">return</span>;
        arr[++top] = x;
    }
    
    <span style="color: #50FA7B">T</span> <span style="color: #50FA7B">pop</span>() {
        <span style="color: #FF79C6">if</span> (top < <span style="color: #BD93F9">0</span>) <span style="color: #FF79C6">return</span> <span style="color: #50FA7B">T</span>();
        <span style="color: #FF79C6">return</span> arr[top--];
    }
};</span>`,

    c: `<span style="color: #FF79C6">#include</span> <span style="color: #50FA7B">&lt;stdio.h&gt;</span>
<span style="color: #FF79C6">#include</span> <span style="color: #50FA7B">&lt;stdlib.h&gt;</span>
<span style="color: #FF79C6">#include</span> <span style="color: #50FA7B">&lt;string.h&gt;</span>

<span style="color: #FF79C6">#define</span> <span style="color: #BD93F9">true</span> <span style="color: #FF79C6">1</span>
<span style="color: #FF79C6">#define</span> <span style="color: #BD93F9">false</span> <span style="color: #FF79C6">0</span>

<span style="color: #FF79C6">typedef</span> <span style="color: #FF79C6">struct</span> {
    <span style="color: #FF79C6">void</span>* arr;
    <span style="color: #FF79C6">int</span> top;
    <span style="color: #FF79C6">int</span> size;
    <span style="color: #FF79C6">size_t</span> element_size;
} <span style="color: #50FA7B">Stack</span>;

<span style="color: #FF79C6">Stack</span>* <span style="color: #50FA7B">init_stack</span>(<span style="color: #FF79C6">int</span> size, <span style="color: #FF79C6">size_t</span> element_size) {
    <span style="color: #FF79C6">Stack</span>* stack = (<span style="color: #FF79C6">Stack</span>*)<span style="color: #FF79C6">malloc</span>(<span style="color: #FF79C6">sizeof</span>(<span style="color: #FF79C6">Stack</span>));
    stack->top = -<span style="color: #BD93F9">1</span>;
    stack->size = size;
    stack->element_size = element_size;
    stack->arr = <span style="color: #FF79C6">malloc</span>(element_size * size);
    <span style="color: #FF79C6">return</span> stack;
}

<span style="color: #FF79C6">void</span> <span style="color: #50FA7B">push</span>(<span style="color: #FF79C6">Stack</span>* stack, <span style="color: #FF79C6">void</span>* element) {
    <span style="color: #FF79C6">if</span> (stack->top >= stack->size - <span style="color: #BD93F9">1</span>) <span style="color: #FF79C6">return</span>;
    stack->top++;
    <span style="color: #FF79C6">void</span>* target = (<span style="color: #FF79C6">char</span>*)stack->arr + stack->top * stack->element_size;
    <span style="color: #FF79C6">memcpy</span>(target, element, stack->element_size);
}

<span style="color: #50FA7B">void*</span> <span style="color: #50FA7B">pop</span>(<span style="color: #FF79C6">Stack</span>* stack) {
    <span style="color: #FF79C6">if</span> (stack->top < <span style="color: #BD93F9">0</span>) <span style="color: #FF79C6">return</span> <span style="color: #FF79C6">NULL</span>;
    <span style="color: #FF79C6">void</span>* element = (<span style="color: #FF79C6">char</span>*)stack->arr + stack->top * stack->element_size;
    stack->top--;
    <span style="color: #FF79C6">return</span> element;
}`,

    java: `<span style="color: #FF79C6">class</span> <span style="color: #50FA7B">Stack</span><span style="color: #BD93F9">&lt;</span><span style="color: #50FA7B">T</span><span style="color: #BD93F9">&gt;</span> {
    <span style="color: #FF79C6">private</span> <span style="color: #50FA7B">T</span>[] arr;
    <span style="color: #FF79C6">private</span> <span style="color: #FF79C6">int</span> top;
    <span style="color: #FF79C6">private</span> <span style="color: #FF79C6">int</span> size;
    
    <span style="color: #50FA7B">Stack</span>(<span style="color: #FF79C6">int</span> s) {
        top = -<span style="color: #BD93F9">1</span>;
        size = s;
        arr = (<span style="color: #50FA7B">T</span>[]) <span style="color: #FF79C6">new</span> <span style="color: #50FA7B">Object</span>[s];
    }
    
    <span style="color: #FF79C6">void</span> <span style="color: #50FA7B">push</span>(<span style="color: #50FA7B">T</span> x) {
        <span style="color: #FF79C6">if</span> (top >= size-<span style="color: #BD93F9">1</span>) <span style="color: #FF79C6">return</span>;
        arr[++top] = x;
    }
    
    <span style="color: #50FA7B">T</span> <span style="color: #50FA7B">pop</span>() {
        <span style="color: #FF79C6">if</span> (top < <span style="color: #BD93F9">0</span>) <span style="color: #FF79C6">return</span> <span style="color: #FF79C6">null</span>;
        <span style="color: #FF79C6">return</span> arr[top--];
    }
}`,

    python: `<span style="color: #FF79C6">class</span> <span style="color: #50FA7B">Stack</span>:
    <span style="color: #FF79C6">def</span> <span style="color: #50FA7B">__init__</span>(<span style="color: #F8F8F2">self</span>, <span style="color: #F8F8F2">size</span>):
        <span style="color: #F8F8F2">self</span>.size = size
        <span style="color: #F8F8F2">self</span>.stack = []
        
    <span style="color: #FF79C6">def</span> <span style="color: #50FA7B">push</span>(<span style="color: #F8F8F2">self</span>, <span style="color: #F8F8F2">item</span>):
        <span style="color: #FF79C6">if</span> <span style="color: #F8F8F2">len</span>(<span style="color: #F8F8F2">self</span>.stack) >= <span style="color: #F8F8F2">self</span>.size:
            <span style="color: #FF79C6">return</span> <span style="color: #FF79C6">None</span>
        <span style="color: #F8F8F2">self</span>.stack.append(item)
        
    <span style="color: #FF79C6">def</span> <span style="color: #50FA7B">pop</span>(<span style="color: #F8F8F2">self</span>):
        <span style="color: #FF79C6">if</span> <span style="color: #F8F8F2">len</span>(<span style="color: #F8F8F2">self</span>.stack) < <span style="color: #BD93F9">1</span>:
            <span style="color: #FF79C6">return</span> <span style="color: #FF79C6">None</span>
        <span style="color: #FF79C6">return</span> <span style="color: #F8F8F2">self</span>.stack.pop()</span>`
  };

  const HowToUseModal = () => (
    showHowToUseModal && (
      <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm">
        <div className="bg-white p-6 rounded-2xl w-full max-w-md max-h-[600px] flex flex-col">
          <h2 className="text-2xl mb-4 text-indigo-900 text-center font-bold">
            How to Use Stack Visualization
          </h2>
          <div className="overflow-y-auto pr-3">
            <div className="space-y-3">
              {[
                "Enter a number between 1 and 999 in the input field.",
                "Click 'Push' to add the number to the stack.",
                "Click 'Pop' to remove the top element from the stack.",
                "Adjust the stack size using the 'Stack Size' input if needed.",
                "Use 'Reset' to clear the entire stack."
              ].map((text, index) => (
                <div key={index} className="flex items-start gap-2.5">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">
                    {index + 1}
                  </span>
                  <p className="text-gray-700">{text}</p>
                </div>
              ))}
            </div>
            
            <div className="mt-4 p-3 bg-blue-50 rounded-lg">
              <h3 className="text-lg font-bold text-indigo-900 mb-2">Keyboard Shortcuts</h3>
              <ul className="space-y-2 text-gray-700">
                <li>• <strong>Enter</strong> - Push number</li>
                <li>• <strong>Delete</strong> - Pop number</li>
                <li>• <strong>Esc</strong> - Close fullscreen</li>
              </ul>
            </div>
          </div>
          <button 
            onClick={() => setShowHowToUseModal(false)}
            className="w-full h-12 bg-indigo-900 text-white font-semibold rounded-lg mt-4 hover:bg-indigo-800"
          >
            Close
          </button>
        </div>
      </div>
    )
  );

  const handleInputChange = (e) => {
    const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 3);
    setInputValue(value);
    setMessage("");
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') push();
    else if (e.key === 'Delete') pop();
  };

  const handleSizeChange = (e) => {
    const newSize = parseInt(e.target.value);
    if (newSize >= 1 && newSize <= 100) {
      setMaxSize(newSize);
      setMessage(`Stack size updated to ${newSize}`);
    } else {
      setMessage("Stack size must be between 1 and 100");
    }
  };

  const push = () => {
    const value = parseInt(inputValue);
    if (isNaN(value) || value < 1 || value > 999) {
      setMessage("Please enter a number between 1 and 999");
      return;
    }
    if (stack.length >= maxSize) {
      setMessage(`Stack is full. Maximum size is ${maxSize}`);
      return;
    }
    setStack([...stack, value]);
    setInputValue("");
    setMessage(`${value} pushed to stack`);
    inputRef.current?.focus();
  };

  const pop = () => {
    if (stack.length === 0) {
      setMessage("Stack is empty");
      return;
    }
    const removedItem = stack[stack.length - 1];
    setStack(stack.slice(0, -1));
    setMessage(`${removedItem} popped from stack`);
  };

  const resetStack = () => {
    setStack([]);
    setMessage("Stack has been reset");
  };

  const togglePage = (direction) => {
    if (direction === 'next' && activeLearningPage < learningPages.length) {
      setActiveLearningPage(prev => prev + 1);
    } else if (direction === 'prev' && activeLearningPage > 1) {
      setActiveLearningPage(prev => prev - 1);
    }
  };

  const learningPages = [
    {
      content: (
        <div className="space-y-4 text-slate-700 flex flex-col items-center justify-center">
          <h2 className="flex text-2xl font-bold text-indigo-900 mb-6 justify-center">What is a Stack?</h2>
          <p>
            A stack is a linear data structure that follows the Last-In-First-Out (LIFO) principle. 
            It's like a stack of plates where you can only add or remove items from the top.
          </p>

          <h3 className="text-xl font-bold text-indigo-800 mt-4">Key Terms</h3>
          <ul className="list-disc pl-6 space-y-2">
            <li><strong>Push:</strong> Adding an element to the top of the stack</li>
            <li><strong>Pop:</strong> Removing an element from the top of the stack</li>
            <li><strong>Top:</strong> The most recently added element</li>
            <li><strong>LIFO:</strong> Last-In-First-Out principle</li>
          </ul>

          <div className="mt-6 bg-slate-100 rounded-xl p-4 flex justify-center items-center w-[80%]">
            <div className="flex flex-col-reverse gap-2">
              {["🍎", "🍐", "🍊"].map((fruit, index) => (
                <div 
                  key={index} 
                  className="w-12 h-12 bg-white border-2 border-indigo-300 rounded-lg flex items-center justify-center text-3xl"
                >
                  {fruit}
                </div>
              ))}
            </div>
            <div className="ml-4 text-slate-600 text-m font-semibold">
              <div>Last In: 🍊</div>
              <div>First Out: 🍊</div>
            </div>
          </div>
        </div>
      )
    },
    {
      content: (
        <div className="space-y-4 text-slate-700 flex flex-col justify-center items-center">
          <h2 className="flex text-2xl font-bold text-indigo-900 mb-6 justify-center">Types and Applications</h2>
          <h3 className="text-xl font-bold text-indigo-800">Stack Variations</h3>
          <ul className="list-disc pl-6 space-y-2">
            <li><strong>Array Stack:</strong> Fixed-size implementation</li>
            <li><strong>Linked Stack:</strong> Dynamic size implementation</li>
            <li><strong>Min/Max Stack:</strong> Tracks minimum/maximum elements</li>
            <li><strong>Call Stack:</strong> Used in program execution</li>
          </ul>

          <h3 className="text-xl font-bold text-indigo-800 mt-6">Real-world Applications</h3>
          <ul className="list-disc pl-6 space-y-2">
            <li><strong>Undo Operations:</strong> Text editors and graphics tools</li>
            <li><strong>Browser History:</strong> Back/forward navigation</li>
            <li><strong>Expression Evaluation:</strong> Processing mathematical expressions</li>
            <li><strong>Function Calls:</strong> Managing program execution</li>
          </ul>
        </div>
      )
    }
  ];

  const renderContent = () => {
    switch (activeSection) {
      case "learn":
        return renderLearningContent();
      case "visualization":
        return renderVisualizationContent();
      case "implementation":
        return renderImplementationContent();
      default:
        return null;
    }
  };

  const renderLearningContent = () => {
    const currentPage = learningPages[activeLearningPage - 1];
    return (
      <div className="flex-grow p-4 flex flex-col overflow-y-auto">
        <div className="flex-grow">
          <h3 className="text-2xl font-bold text-indigo-800 mb-4">
            {currentPage.title}
          </h3>
          {currentPage.content}
        </div>
        
        <div className="flex justify-center items-center gap-4 mt-6">
          <button 
            onClick={() => togglePage('prev')} 
            disabled={activeLearningPage === 1}
            className={`p-2 rounded-full ${activeLearningPage === 1 ? 'bg-slate-200' : 'bg-indigo-100 hover:bg-indigo-200'}`}
          >
            <ChevronLeft className={`w-6 h-6 ${activeLearningPage === 1 ? 'text-slate-400' : 'text-indigo-800'}`} />
          </button>
          <span className="text-slate-600">
            Page {activeLearningPage} of {learningPages.length}
          </span>
          <button 
            onClick={() => togglePage('next')} 
            disabled={activeLearningPage === learningPages.length}
            className={`p-2 rounded-full ${activeLearningPage === learningPages.length ? 'bg-slate-200' : 'bg-indigo-100 hover:bg-indigo-200'}`}
          >
            <ChevronRight className={`w-6 h-6 ${activeLearningPage === learningPages.length ? 'text-slate-400' : 'text-indigo-800'}`} />
          </button>
        </div>
      </div>
    );
  };

  const renderVisualizationContent = () => (
    <div className="flex-grow p-4 overflow-y-auto">
      <div className="flex justify-center items-center gap-4">
        <h1 className="text-xl md:text-3xl font-bold bg-gradient-to-r from-indigo-900 to-indigo-600 bg-clip-text text-transparent">
          Stack Visualization
        </h1>
        <button 
          className="text-xl md:text-2xl text-indigo-900 hover:bg-indigo-100 rounded p-1"
          onClick={() => setShowHowToUseModal(true)}
        >
          ℹ️
        </button>
      </div>

      <div className="bg-slate-50 rounded-xl p-6 border-2 border-slate-200 shadow-inner mb-6 h-60 mt-4">
        <div className="w-full h-full overflow-y-auto">
          <div className="flex flex-col-reverse items-center gap-4 h-full overflow-y-auto">
            {stack.length === 0 ? (
              <p className="text-slate-400 italic w-full text-center">
                Stack is empty
              </p>
            ) : (
              stack.map((item, index) => (
                <div 
                  key={index}
                  className="relative w-[65%] md:w-[65%] h-16 md:h-20 flex items-center justify-center text-white text-xl md:text-2xl font-bold rounded-xl shadow-md flex-shrink-0 transition-transform duration-200 cursor-default"
                  style={{ backgroundColor: `hsl(${200 + index * 15}, 75%, 65%)` }}
                >
                  {item}
                  {index === stack.length - 1 && (
                    <span className="absolute left-full ml-4 text-xs text-slate-600 font-medium">
                      Top = {index}
                    </span>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>

      <div className="flex items-center gap-3 mb-4 justify-center">
        <label className="text-slate-600 font-medium">Stack Size:</label>
        <input 
          type="number"
          min="1"
          max="100"
          value={maxSize}
          onChange={handleSizeChange}
          className="w-20 p-2 rounded-lg border-2 border-slate-300 text-center"
        />
      </div>

      <div className="space-y-4 px-4">
        <div className="flex flex-col md:flex-row gap-4">
          <input
            type="text"
            value={inputValue}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            ref={inputRef}
            placeholder="Enter value (1-999)"
            className="flex-1 p-3.5 rounded-lg border-2 border-slate-300"
          />
          <button
            onClick={push}
            className="md:w-32 px-7 py-3.5 rounded-lg text-white font-semibold bg-blue-500 hover:bg-blue-600 transition-colors"
          >
            Push
          </button>
        </div>
        
        <div className="flex justify-center gap-4">
          <button
            onClick={pop}
            className="px-7 py-3.5 rounded-lg text-white font-semibold bg-emerald-500 hover:bg-emerald-600 transition-colors w-32"
          >
            Pop
          </button>
          <button
            onClick={resetStack}
            className="px-7 py-3.5 rounded-lg text-white font-semibold bg-red-500 hover:bg-red-600 transition-colors w-32"
          >
            Reset
          </button>
        </div>
      </div>

      {message && (
        <div className={`mt-5 p-3.5 rounded-lg font-semibold text-center
          ${message.includes("between") || message.includes("full") || message.includes("empty")
            ? "bg-red-100 text-red-600"
            : "bg-green-100 text-green-600"
          }`}
        >
          {message}
        </div>
      )}
    </div>
  );

  const renderImplementationContent = () => (
    <div className="flex-grow p-4 overflow-y-auto">
      <h2 className="text-2xl md:text-3xl font-bold bg-gradient-to-r from-indigo-900 to-indigo-600 bg-clip-text text-transparent text-center mb-4">
        Implementation
      </h2>

      <select
        value={selectedLanguage}
        onChange={(e) => setSelectedLanguage(e.target.value)}
        className="w-full p-3 rounded-lg border-2 border-slate-200 mb-4"
      >
        <option value="pseudo">Pseudocode</option>
        <option value="cpp">C++</option>
        <option value="c">C</option>
        <option value="python">Python</option>
        <option value="java">Java</option>
      </select>

      <pre className="bg-gray-900 text-white p-5 overflow-auto rounded-2xl leading-relaxed">
        <code dangerouslySetInnerHTML={{ __html: codeExamples[selectedLanguage] }} />
      </pre>

    <div className="mt-6 p-4 bg-blue-50 rounded-lg border border-blue-100">
      <h3 className="text-lg font-bold text-indigo-900 mb-2">
        Implementation Notes
      </h3>
      <ul className="space-y-2 text-gray-700">
        <li className="flex items-start gap-2">
          <span className="text-indigo-500">•</span>
          <strong>Time Complexity:</strong> O(1) for push and pop operations
        </li>
        <li className="flex items-start gap-2">
          <span className="text-indigo-500">•</span>
          <strong>Space Complexity:</strong> O(n) where n is the number of elements
        </li>
        <li className="flex items-start gap-2">
          <span className="text-indigo-500">•</span>
          <strong>Best used when:</strong>You need LIFO (Last In First Out) operations or need to track function calls/recursion
        </li>
        <li className="flex items-start gap-2">
          <span className="text-indigo-500">•</span>
          <strong>Common applications:</strong> Function call stack, undo operations, expression evaluation
        </li>
      </ul>
    </div>
    </div>
  );

  return (
    <div className="flex flex-col w-full gap-6 p-4 bg-gradient-to-br from-blue-50 to-blue-100 min-h-screen">
      <div className={`relative w-full transition-all duration-300 ease-in-out h-[700px]
        bg-white rounded-2xl shadow-lg p-0 flex flex-col`}>
        
        <div className="flex p-0 justify-around items-center border-b-2 h-[8vh] z-50">
          <div 
            onClick={() => setActiveSection("learn")}
            className={`w-1/3 text-center border-r-2 h-[50px] flex items-center justify-center cursor-pointer
              ${activeSection === "learn" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Learn
          </div>
          
          <div 
            onClick={() => setActiveSection("visualization")}
            className={`w-1/3 text-center border-r-2 h-[50px] flex items-center justify-center cursor-pointer
              ${activeSection === "visualization" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Visualize
          </div>

          <div 
            onClick={() => setActiveSection("implementation")}
            className={`w-1/3 text-center h-[50px] flex items-center justify-center cursor-pointer
              ${activeSection === "implementation" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Code
          </div>
        </div>

        {renderContent()}
      </div>
      
      <Navigation currentPage="stack-learn" />
      {HowToUseModal()}
    </div>
  );
};

export default StackVisualization;
