import React, { useState } from 'react';
import { ChevronDown, ChevronUp, Home } from 'lucide-react';
import { useNavigate, useLocation } from 'react-router-dom';
import Swal from 'sweetalert2';

const Navigation = ({ currentPage }) => {
  const [isOpen, setIsOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  const pagesWithGames = {
    'queue': {
      gamePath: '/queuegame',
      title: 'Queue Game Available! 🎮',
      description: 'Want to test your understanding of Queues through an interactive game? It\'s a fun way to reinforce what you\'ve learned!',
    },
    'stack': {
      gamePath: '/water',
      title: 'Stack Challenge Awaits! 🎮',
      description: 'Ready to put your Stack knowledge to the test? We\'ve got an exciting game that will help you master the concept!',
    },
    'linkedlist': {
      gamePath: '/ll-game',
      title: 'Linked List Game Ready! 🎮',
      description: 'Time to practice your Linked List skills with an interactive challenge!',
    },
    'bst': {
      gamePath: '/bstgame',
      title: 'BST Game Available! 🎮',
      description: 'Test your Binary Search Tree knowledge with our interactive game!',
    },
    'hashlearn': {
      gamePath: '/hashing-game',
      title: 'Hash Table Challenge! 🎮',
      description: 'Ready to reinforce your Hashing concepts with a fun game?',
    },
    'huffman': {
      gamePath: '/huffmangame',
      title: 'Huffman Coding Game! 🎮',
      description: 'Practice Huffman Coding with our interactive challenge!',
    }
  };

  const allPages = [
    { id: 'data-structures', name: 'Data Structures', path: '/' },
    { id: 'algorithms', name: 'Algorithms', path: '/algohome' },
  ];

  const navigationOptions = allPages.filter(page => page.path !== location.pathname);

  const handleNavigation = (targetPath) => {
    const currentPathWithoutSlash = location.pathname.slice(1);
    const currentPageGame = pagesWithGames[currentPathWithoutSlash];
    
    if (currentPageGame) {
      Swal.fire({
        title: currentPageGame.title,
        text: currentPageGame.description,
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: 'Yes, let\'s play!',
        cancelButtonText: 'Maybe later',
        confirmButtonColor: '#4338CA', 
        cancelButtonColor: '#4B5563', 
        background: '#FFFFFF',
        iconColor: '#4338CA',
        customClass: {
          title: 'text-2xl font-bold text-gray-900 mb-4',
          text: 'text-gray-700 text-base leading-relaxed mb-6',
          confirmButton: 'px-6 py-3 rounded-lg text-sm font-semibold transition-all hover:scale-105',
          cancelButton: 'px-6 py-3 rounded-lg text-sm font-semibold transition-all hover:opacity-90',
          popup: 'rounded-2xl border border-gray-100 shadow-2xl p-6',
          container: 'backdrop-blur-sm'
        },
        showClass: {
          popup: 'animate__animated animate__fadeIn animate__faster'
        },
        hideClass: {
          popup: 'animate__animated animate__fadeOut animate__faster'
        },
        padding: '2em',
        width: 'auto',
        backdrop: `rgba(0,0,0,0.4)`
      }).then((result) => {
        if (result.isConfirmed) {
          navigate(currentPageGame.gamePath);
        } else {
          navigate(targetPath);
        }
      });
    } else {
      navigate(targetPath);
    }
  };

  return (
    <div className="fixed bottom-7 left-7 right-7 z-50">
      <div className="flex justify-between items-center">
        <button
          onClick={() => handleNavigation('/')}
          className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg transition-colors shadow-lg"
        >
          <Home className="w-5 h-5" />
          <span className="hidden sm:inline">Home</span>
        </button>

        <div className="relative">
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg transition-colors shadow-lg"
          >
            <span>Go to</span>
            {isOpen ? (
              <ChevronUp className="w-5 h-5" />
            ) : (
              <ChevronDown className="w-5 h-5" />
            )}
          </button>

          {isOpen && (
            <div className="absolute bottom-full right-0 mb-2 w-48 bg-white rounded-lg shadow-xl border border-gray-200 max-h-96 overflow-y-auto">
              {navigationOptions.map((option) => (
                <button
                  key={option.id}
                  onClick={() => {
                    handleNavigation(option.path);
                    setIsOpen(false);
                  }}
                  className="w-full text-left px-4 py-2 hover:bg-indigo-50 text-gray-700 hover:text-indigo-600 transition-colors first:rounded-t-lg last:rounded-b-lg"
                >
                  {option.name}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Navigation;