import React, { useState, useEffect } from "react";
import Swal from "sweetalert2";
import withReactContent from "sweetalert2-react-content";
import "./HashTableGame.css";
import mountainCave from "../Images/HashGame/Mountain Cave.jpg";
import sandyBeach from "../Images/HashGame/Sandy Beach.jpg";
import denseJungle from "../Images/HashGame/Dense Jungle.jpg";
import abandoned from "../Images/HashGame/Abandoned Shipwreck.jpg";
import hidWaterfall from "../Images/HashGame/hidWater.webp";
import meadow from "../Images/HashGame/meadow.webp";
import darkForest from "../Images/HashGame/Dark Forest.webp";
import coralReef from "../Images/HashGame/Coral Reef.png";
import volcano from "../Images/HashGame/Volcano.webp";
import crystalPond from "../Images/HashGame/Crystal Pond.webp";

import rubyImage from "../Images/HashGame/ruby.png";
import emeraldImage from "../Images/HashGame/emerald.png";
import sapphireImage from "../Images/HashGame/sapphire.png";
import goldCoinImage from "../Images/HashGame/goldCoin.png";
import diamondImage from "../Images/HashGame/diamond.png";
import scrollImage from "../Images/HashGame/scroll.png";

const MySwal = withReactContent(Swal);

const LOCATIONS = [
  { id: 0, name: "Mountain Cave", image: mountainCave },
  { id: 1, name: "Sandy Beach", image: sandyBeach },
  { id: 2, name: "Dense Jungle", image: denseJungle },
  { id: 3, name: "Abandoned Shipwreck", image: abandoned },
  { id: 4, name: "Hidden Waterfall", image: hidWaterfall },
  { id: 5, name: "Sunny Meadow", image: meadow },
  { id: 6, name: "Dark Forest", image: darkForest },
  { id: 7, name: "Volcanic Ridge", image: volcano },
  { id: 8, name: "Coral Reef", image: coralReef },
  { id: 9, name: "Crystal Pond", image: crystalPond }
];

const VALUABLES = [
  { name: "Ruby", value: 0, image: rubyImage },
  { name: "Emerald", value: 0, image: emeraldImage },
  { name: "Sapphire", value: 0, image: sapphireImage },
  { name: "Gold Coin", value: 0, image: goldCoinImage },
  { name: "Diamond", value: 0, image: diamondImage },
  { name: "Ancient Scroll", value: 0, image: scrollImage }
];
const HashTableGame = () => {
  const [currentLevel, setCurrentLevel] = useState(1);
  const [foundValuables, setFoundValuables] = useState(0);
  const [guessedValuables, setGuessedValuables] = useState(new Set());
  const [locationsStatus, setLocationsStatus] = useState([]);
  const [chainedLocations, setChainedLocations] = useState([]);
  const [currentValuable, setCurrentValuable] = useState(null);
  const [remainingValuables, setRemainingValuables] = useState([]);
  const [lives, setLives] = useState(2);
  const [mistakes, setMistakes] = useState(0);

  const initializeLevel = () => {
    setFoundValuables(0);
    setGuessedValuables(new Set());
    setLives(2);
    setMistakes(0);

    const initializedValuables = VALUABLES.map(valuable => ({
      ...valuable,
      value: Math.floor(Math.random() * 901) + 100
    }));
    setRemainingValuables(initializedValuables);
    setCurrentValuable(initializedValuables[0]);

    if (currentLevel === 1) {
      // Linear Probing
      const locations = new Array(10).fill(null);
      initializedValuables.forEach(valuable => {
        let index = valuable.value % LOCATIONS.length;
        while (locations[index] !== null) {
          index = (index + 1) % LOCATIONS.length;
        }
        locations[index] = valuable.name;
      });
      setLocationsStatus(locations);
      setChainedLocations([]);
    } else if (currentLevel === 2) {
      const locations = new Array(10).fill(null);
      initializedValuables.forEach(valuable => {
        let i = 0;
        let index = (valuable.value + i * i) % LOCATIONS.length;
        while (locations[index] !== null) {
          i++;
          index = (valuable.value + i * i) % LOCATIONS.length;
        }
        locations[index] = valuable.name;
      });
      setLocationsStatus(locations);
      setChainedLocations([]);
    } else {
      const chains = Array(10).fill(null).map(() => []);
      initializedValuables.forEach(valuable => {
        const index = valuable.value % LOCATIONS.length;
        chains[index].push(valuable.name);
      });
      setChainedLocations(chains);
      setLocationsStatus([]);
    }
    const probingMethod = currentLevel === 1 ? "Linear Probing" : 
                         currentLevel === 2 ? "Quadratic Probing" : 
                         "Chaining";
    MySwal.fire({
      title: `Welcome to Level ${currentLevel}!`,
      html: `
        <p>This level uses <strong>${probingMethod}</strong> to hide treasures.</p>
        <p>You have 2 lives. Choose carefully!</p>
        <p>Find at least 4 valuables to advance to the next level!</p>
        ${currentLevel === 3 ? "<p>In this level, locations can contain multiple treasures!</p>" : ""}
      `,
      icon: "info",
      confirmButtonText: "Start Level"
    });
  };

  useEffect(() => {
    initializeLevel();
  }, [currentLevel]);

  const moveToNextValuable = () => {
    const nextValuables = remainingValuables.filter(v => !guessedValuables.has(v.name));
    setCurrentValuable(nextValuables[0] || null);
    setMistakes(0);
    setLives(2);
  };

  const handleLocationClick = async (locationId) => {
    if (!currentValuable || lives === 0) return;

    if (currentLevel === 3) {
      // Chaining level logic
      const valuablesAtLocation = chainedLocations[locationId];
      if (!valuablesAtLocation.includes(currentValuable.name)) {
        setMistakes(prev => prev + 1);
        setLives(prev => prev - 1);
        
        if (lives === 1) {
          setGuessedValuables(prev => new Set([...prev, currentValuable.name]));
          moveToNextValuable();
          await MySwal.fire({
            title: "Out of Lives!",
            text: "Moving to next valuable...",
            icon: "error",
            confirmButtonText: "Continue"
          });
        } else {
          await MySwal.fire({
            title: "Incorrect Location!",
            text: `1 life remaining for ${currentValuable.name}`,
            icon: "warning",
            confirmButtonText: "Try Again"
          });
        }
        return;
      }
      setGuessedValuables(prev => new Set([...prev, currentValuable.name]));
      setFoundValuables(prev => prev + 1);

      await MySwal.fire({
        title: "Treasure Found!",
        html: `
          <div class="text-center">
            <img src="${currentValuable.image}" alt="${currentValuable.name}" class="mx-auto mb-4 w-32 h-32"/>
            <p>You found the ${currentValuable.name}!</p>
            <p>${4 - (foundValuables + 1)} more needed to advance.</p>
          </div>
        `,
        icon: "success",
        confirmButtonText: "Continue"
      });

      moveToNextValuable();
      checkLevelProgress();
    } else {
      const foundValuable = locationsStatus[locationId];

      if (foundValuable !== currentValuable.name) {
        setMistakes(prev => prev + 1);
        setLives(prev => prev - 1);
        
        if (lives === 1) {
          setGuessedValuables(prev => new Set([...prev, currentValuable.name]));
          moveToNextValuable();
          await MySwal.fire({
            title: "Out of Lives!",
            text: "Moving to next valuable...",
            icon: "error",
            confirmButtonText: "Continue"
          });
        } else {
          await MySwal.fire({
            title: "Incorrect Location!",
            text: `1 life remaining for ${currentValuable.name}`,
            icon: "warning",
            confirmButtonText: "Try Again"
          });
        }
        return;
      }

      // Found correct valuable
      setGuessedValuables(prev => new Set([...prev, foundValuable]));
      setFoundValuables(prev => prev + 1);

      await MySwal.fire({
        title: "Treasure Found!",
        html: `
          <div class="text-center">
            <img src="${currentValuable.image}" alt="${currentValuable.name}" class="mx-auto mb-4 w-32 h-32"/>
            <p>You found the ${currentValuable.name}!</p>
            <p>${4 - (foundValuables + 1)} more needed to advance.</p>
          </div>
        `,
        icon: "success",
        confirmButtonText: "Continue"
      });

      moveToNextValuable();
      checkLevelProgress();
    }
  };

  const checkLevelProgress = async () => {
    if (foundValuables + 1 >= 6) {
      if (currentLevel < 3) {
        const result = await MySwal.fire({
          title: "Level Complete!",
          text: "You've found enough valuables! Ready for the next level?",
          icon: "success",
          confirmButtonText: "Next Level"
        });
        if (result.isConfirmed) {
          setCurrentLevel(prev => prev + 1);
        }
      } else {
        await MySwal.fire({
          title: "Congratulations!",
          text: "You've completed all levels! You're a master treasure hunter!",
          icon: "success",
          confirmButtonText: "Play Again"
        });
        setCurrentLevel(1);
      }
    }
  };

  return (
    <div className="min-h-screen w-full bg-gradient-to-br from-violet-200 via-pink-200 to-yellow-200 relative p-4">
    <div className="absolute inset-0">
      <div className="absolute top-0 left-0 w-72 h-72 bg-pink-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-tl"></div>
      <div className="absolute top-0 right-0 w-72 h-72 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-tr"></div>
      <div className="absolute bottom-0 left-0 w-72 h-72 bg-blue-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-bl"></div>
      <div className="absolute bottom-0 right-0 w-72 h-72 bg-green-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-br"></div>
      <div className="absolute left-1/2 -translate-x-1/2 top-1/2 -translate-y-1/2 w-96 h-96 bg-yellow-300 rounded-full mix-blend-multiply filter blur-xl opacity-50 animate-pulse"></div>
    </div>
      <div className="h-0.5 mx-auto">
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold text-gray-800 mb-4 mt-4">
            Treasure Hunt Island - Level {currentLevel} {currentLevel === 1 
        ? "Linear probing" 
        : currentLevel === 2 
        ? "Quadratic probing"
        : "Chaining"}
          </h1>
          <p className="text-lg text-gray-600 mb-2">
            Lives Remaining: {lives}
          </p>
          {currentValuable && (
  <div className="bg-white rounded-lg shadow-md p-4 max-w-md mx-auto mb-6">
    <h2 className="text-xl font-semibold mb-2"></h2>
    <p className="text-lg text-blue-600">Currently Searching For: {currentValuable.name}</p>
    <p className="text-md text-gray-600">Value: {currentValuable.value}</p>
    <p className="text-sm text-purple-600 mt-2">
      
    </p>
  </div>
)}
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 px-4">
          {LOCATIONS.map((location) => (
            <div
              key={location.id}
              onClick={() => handleLocationClick(location.id)}
              className="relative bg-white rounded-lg shadow-lg cursor-pointer transform transition-transform hover:scale-105"
            >
              <img 
                src={location.image} 
                alt={location.name}
                className="w-full h-40 object-cover"
              />
              <div className="p-2">
                <h3 className="text-lg font-semibold text-gray-800 mb-2">
                  {location.name}
                </h3>
                <p className="text-sm text-gray-600">Index: {location.id}</p>
                
              </div>
            </div>
          ))}
        </div>
      </div>
  </div>
  </div>
  );
};

export default HashTableGame;