import React, { useState, useEffect } from 'react';
import Swal from 'sweetalert2';
import Navigation from '../Navigation';

const CITY_COLORS = {
  'Paris': 'rgba(255, 105, 180, 0.9)',
  'London': 'rgba(65, 105, 225, 0.9)',
  'Berlin': 'rgba(50, 205, 50, 0.9)',
  'Rome': 'rgba(255, 140, 0, 0.9)',
  'Madrid': 'rgba(138, 43, 226, 0.9)'
};

const DESTINATIONS = Object.keys(CITY_COLORS);
const TOTAL_PASSENGERS = 15;

const PassengerIcon = ({ color, size = 40 }) => (
  <svg viewBox="3 0 18 18" width={size} height={size}>
    <circle cx="12" cy="7" r="4" fill={color} />
    <path d="M12 11c-3.314 0-6 1.686-6 3.75V17h12v-2.25c0-2.064-2.686-3.75-6-3.75z" fill={color} />
    <circle cx="12" cy="7" r="4" fill={color} stroke="black" strokeWidth="0.5" />
    <path d="M12 11c-3.314 0-6 1.686-6 3.75V17h12v-2.25c0-2.064-2.686-3.75-6-3.75z" fill={color} stroke="black" strokeWidth="0.5" />
  </svg>
);

const TrainIcon = ({ destination, color, onClick }) => (
  <button
    onClick={onClick}
    className="relative transform hover:scale-105 transition-transform"
    style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}
  >
    <svg viewBox="0 0 200 80" width="120" height="48" className="w-[120px] h-[48px] md:w-[200px] md:h-[80px]">
      {/* Passenger Car */}
      <rect x="30" y="20" width="60" height="40" fill={color} rx="5" />
      <rect x="40" y="25" width="15" height="20" fill="white" rx="2" />
      <rect x="65" y="25" width="15" height="20" fill="white" rx="2" />
      
      {/* Passenger Car Wheels */}
      <circle cx="45" cy="60" r="7" fill="black" />
      <circle cx="75" cy="60" r="7" fill="black" />
      <circle cx="45" cy="60" r="3" fill="#666" />
      <circle cx="75" cy="60" r="3" fill="#666" />

      {/* Connector */}
      <rect x="90" y="50" width="8" height="3" fill="black" rx="1" />

      {/* Locomotive */}
      <rect x="98" y="10" width="40" height="50" fill={color} rx="5" />
      <rect x="138" y="34" width="20" height="25" fill={color} rx="2" />
      <rect x="115" y="18" width="15" height="15" fill="white" rx="2" />
      
      {/* Smokestack */}
      <rect x="143" y="27" width="7" height="8" fill="black" rx="1" />
      <rect x="141" y="24" width="11" height="4" fill="black" rx="1" />
      
      {/* Locomotive Wheels */}
      <circle cx="110" cy="60" r="7" fill="black" />
      <circle cx="130" cy="60" r="7" fill="black" />
      <circle cx="110" cy="60" r="3" fill="#666" />
      <circle cx="130" cy="60" r="3" fill="#666" />
    </svg>
    <div className="text-sm font-semibold text-center mt-1 text-black">{destination}</div>
  </button>
);

const generatePassenger = () => {
  const destination = DESTINATIONS[Math.floor(Math.random() * DESTINATIONS.length)];
  const color = CITY_COLORS[destination];
  return { color, destination };
};

const shuffleArray = (array) => {
  const newArray = [...array];
  for (let i = newArray.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
  }
  return newArray;
};

const QueueGame = () => {
  const [queue, setQueue] = useState([]);
  const [trains, setTrains] = useState([]);
  const [score, setScore] = useState(0);
  const [lives, setLives] = useState(3);
  const [gameOver] = useState(false);
  const [currentPassenger, setCurrentPassenger] = useState(null);
  const [showInstructions, setShowInstructions] = useState(false);
  const [remainingPassengers, setRemainingPassengers] = useState(TOTAL_PASSENGERS);
  const [gameStarted, setGameStarted] = useState(false);
  const [processedPassengers, setProcessedPassengers] = useState(0);

  useEffect(() => {
    if (!gameStarted) {
      showWelcomeMessage();
    }
  }, []);

  useEffect(() => {
    if (lives <= 0) {
      showGameEndAlert(false);
    } else if (processedPassengers === TOTAL_PASSENGERS && queue.length === 0 && !currentPassenger) {
      showGameEndAlert(true);
    }
  }, [lives, processedPassengers, queue.length, currentPassenger]);

  const showWelcomeMessage = async () => {
    const result = await Swal.fire({
      title: '🎮 Welcome, Station Master! 🚂',
      html: `
        <div class="text-left">
          <p class="mb-4">You've been appointed as the new Station Master of Europa Central Station!</p>
          <p class="mb-4">Your Challenge:</p>
          <ul class="list-disc pl-5 mb-4">
            <li>Guide ${TOTAL_PASSENGERS} passengers to their correct destinations</li>
            <li>Manage a queue of up to 6 passengers</li>
            <li>Ensure passengers board the right trains</li>
            <li>Avoid making more than 3 mistakes</li>
          </ul>
          <p class="mb-4">Score 10 points for each correct boarding!</p>
          <p class="text-sm italic">Are you ready to prove yourself as the Ultimate Station Master?</p>
        </div>
      `,
      icon: 'question',
      confirmButtonText: 'Accept the Challenge!',
      confirmButtonColor: '#4CAF50',
      background: '#f8f9fa',
      backdrop: `rgba(0,0,123,0.4)`
    });

    if (result.isConfirmed) {
      setGameStarted(true);
      setCurrentPassenger(generatePassenger());
      setTrains(shuffleArray(DESTINATIONS).slice(0, 3));
    }
  };

  const showGameEndAlert = (isVictory) => {
    const title = isVictory ? '🏆 Spectacular Success!' : '📉 Station Management Crisis';
    const html = isVictory 
      ? `
        <p class="mb-4">Outstanding work, Station Master!</p>
        <p class="mb-4">You've successfully managed the station with a score of <strong>${score} points!</strong> </p>
        <p class="mb-4">The Railway Board is impressed!</p>
      `
      : `
        <p class="mb-4">Unfortunately, too many errors have occurred.</p>
        <p class="mb-4">Your final score: <strong>${score} points</strong> </p>
        <p class="mb-4">The Railway Board suggests additional training.</p>
      `;

    
    Swal.fire({
      title,
      html,
      icon: isVictory ? 'success' : 'error',
      confirmButtonText: 'Return to Home',
      confirmButtonColor: isVictory ? '#4CAF50' : '#f44336',
      showConfirmButton: true,
      allowOutsideClick: false,
      customClass: {
        htmlContainer: 'swal-custom-html'
      }
    }).then((result) => {
      if (result.isConfirmed) {
        window.location.href = '/';
      }
    });
};
  useEffect(() => {
    if (!gameOver && !currentPassenger && remainingPassengers > 0 && gameStarted) {
      const timer = setTimeout(() => {
        const newPassenger = generatePassenger();
        setCurrentPassenger(newPassenger);
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [currentPassenger, gameOver, remainingPassengers, gameStarted]);

  useEffect(() => {
    if (!gameOver && gameStarted) {
      const timer = setTimeout(() => {
        const availableDestinations = shuffleArray(DESTINATIONS);
        setTrains(prev => {
          const newTrains = [...prev.slice(1)];
          const validDestinations = availableDestinations.filter(
            dest => !newTrains.includes(dest)
          );
          newTrains.push(validDestinations[0]);
          return newTrains;
        });
      }, 4000);

      return () => clearTimeout(timer);
    }
  }, [trains, gameOver, gameStarted]);

  const addToQueue = () => {
    if (currentPassenger && queue.length < 6) {
      setQueue(prev => [...prev, currentPassenger]);
      setCurrentPassenger(null);
      setRemainingPassengers(prev => prev - 1);
    }
  };

  const boardTrain = (trainDestination) => {
  if (queue.length === 0) return;
  
  const firstPassenger = queue[0];
  if (firstPassenger.destination === trainDestination) {
    setQueue(prev => prev.slice(1));
    setScore(prev => prev + 10);
    setProcessedPassengers(prev => prev + 1);
  } else {
    setLives(prev => prev - 1);
    Swal.fire({
      title: 'Wrong Train!',
      html: `
        <div class="flex flex-col items-center">
          <div class="mb-4">
            <span class="text-4xl">💔</span>
            <span class="text-red-500 text-xl ml-2">Life -1</span>
          </div>
          <p>This passenger needs to go to ${firstPassenger.destination}!</p>
        </div>
      `,
      icon: 'error',
      timer: 1500
    });
  }
};

  return (
    <div className="min-h-screen w-full bg-gradient-to-br from-violet-200 via-pink-200 to-yellow-200 relative overflow-hidden">
      <div className="absolute inset-0">
        <div className="absolute top-0 left-0 w-36 md:w-72 h-36 md:h-72 bg-pink-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-tl"></div>
        <div className="absolute top-0 right-0 w-36 md:w-72 h-36 md:h-72 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-tr"></div>
        <div className="absolute bottom-0 left-0 w-36 md:w-72 h-36 md:h-72 bg-blue-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-bl"></div>
        <div className="absolute bottom-0 right-0 w-36 md:w-72 h-36 md:h-72 bg-green-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob-br"></div>
        <div className="absolute left-1/2 -translate-x-1/2 top-1/2 -translate-y-1/2 w-48 md:w-96 h-48 md:h-96 bg-yellow-300 rounded-full mix-blend-multiply filter blur-xl opacity-50 animate-pulse"></div>
      </div>
  
      <div className="relative min-h-screen flex items-center justify-center p-2 md:p-4">
        <div className="w-full max-w-4xl bg-white/80 backdrop-blur-md rounded-xl shadow-2xl p-3 md:p-8" style={{border: '3px solid black'}}>
          <div className="text-center mb-4 md:mb-8">
            <div className="flex justify-center items-center gap-2 md:gap-4 mb-4 md:mb-6">
              <h1 className="text-xl md:text-3xl font-bold text-black">Train Station Queue Manager</h1>
              <button onClick={() => setShowInstructions(true)} className="p-1 md:p-2 text-xl md:text-2xl hover:bg-indigo-100 rounded">
                ℹ️
              </button>
            </div>
            <div className="flex flex-col md:flex-row justify-center gap-2 md:gap-8 text-base md:text-xl font-semibold text-black">
              <div>Score: {score}</div>
              <div className="text-red-500 text-xl">❤️ {lives}</div>
              <div>Passengers: {remainingPassengers}</div>
            </div>
          </div>
  
          <div className="flex flex-wrap justify-center gap-2 md:gap-4 mb-4 md:mb-8">
            {Object.entries(CITY_COLORS).map(([city, color]) => (
              <div key={city} className="flex items-center gap-1 md:gap-2">
                <div className="w-3 md:w-4 h-3 md:h-4 rounded-full" style={{ backgroundColor: color }} />
                <span className="text-xs md:text-sm text-black">{city}</span>
              </div>
            ))}
          </div>
  
          <div className="flex justify-center mb-4 md:mb-8">
  <div className="text-center w-32 h-32 flex flex-col items-center justify-center">
    <h2 className="text-base md:text-lg font-semibold mb-2 text-black">Next Passenger</h2>
    <div className="h-16 flex flex-col items-center justify-center">
      {currentPassenger ? (
        <>
          <PassengerIcon color={currentPassenger.color} size={48} />
          <div className="text-sm md:text-base text-black mt-1">To: {currentPassenger.destination}</div>
        </>
      ) : (
        <div className="text-sm text-gray-500">
          {remainingPassengers > 0 ? "Awaiting passenger..." : "All passengers served! 🎉"}
        </div>
      )}
    </div>
        {currentPassenger && (
          <button
            onClick={addToQueue}
            disabled={queue.length >= 6}
            className="mt-2 px-6 py-1 text-sm md:text-base bg-green-500 text-white rounded hover:bg-green-600 disabled:bg-gray-300 whitespace-nowrap"
          >
            Add to Queue
          </button>
        )}
      </div>
    </div>
  
          <div className="mb-4 md:mb-8">
            <h2 className="text-base md:text-lg font-semibold mb-2 text-center text-black">Passenger Queue</h2>
            <div className="flex justify-center gap-2 md:gap-4">
              {Array(6).fill(null).map((_, i) => (
                <div key={i} className="w-16 h-20 border-2 border-gray-300 rounded-lg flex flex-col items-center justify-center bg-white/50">
                  {queue[i] && (
                    <>
                      <PassengerIcon color={queue[i].color} size={32} />
                      <div className="text-[10px] md:text-xs text-black">{queue[i].destination}</div>
                    </>
                  )}
                </div>
              ))}
            </div>
          </div>
  
          <div>
            <h2 className="text-base md:text-lg font-semibold mb-2 text-center text-black">Available Trains</h2>
            <div className="flex flex-row justify-center gap-2 md:gap-4 px-2">
              {trains.map((destination, i) => (
                <TrainIcon
                  key={i}
                  destination={destination}
                  color={CITY_COLORS[destination]}
                  onClick={() => boardTrain(destination)}
                />
              ))}
            </div>
          </div>
        </div>
      </div>

      {showInstructions && (
        <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm">
          <div className="bg-white p-8 rounded-2xl max-w-[500px] w-[90%]">
            <h2 className="text-2xl mb-5 text-indigo-900 text-center font-bold">
              How to Play
            </h2>
            <div className="flex items-center gap-2.5 mb-4">
              <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">1</span>
              <p className="text-gray-700">New passengers arrive wanting to go to different destinations. There are {TOTAL_PASSENGERS} passengers in total.</p>
            </div>
            <div className="flex items-center gap-2.5 mb-4">
              <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">2</span>
              <p className="text-gray-700">Add them to the queue when they arrive (maximum 6 passengers in line).</p>
            </div>
            <div className="flex items-center gap-2.5 mb-4">
              <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">3</span>
              <p className="text-gray-700">When trains arrive, the first passenger in line (FIFO) must board their matching train.</p>
            </div>
            <div className="flex items-center gap-2.5 mb-4">
              <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">4</span>
              <p className="text-gray-700">Score 10 points for each correct boarding. You have 3 lives - be careful not to lose them all!</p>
            </div>
            <button
              onClick={() => setShowInstructions(false)}
              className="w-full h-12 bg-indigo-900 text-white text-base font-semibold rounded-lg cursor-pointer flex justify-center items-center mt-8 transition-all duration-300 hover:bg-indigo-800"
            >
              Close
            </button>
          </div>
        </div>
      )}
  
      <style jsx>{`
        @keyframes blob-tl {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(calc(100vw - 18rem), 0) scale(1.1); }
          50% { transform: translate(calc(100vw - 18rem), calc(100vh - 18rem)) scale(1); }
          75% { transform: translate(0, calc(100vh - 18rem)) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-tr {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(0, calc(100vh - 18rem)) scale(1.1); }
          50% { transform: translate(calc(-100vw + 18rem), calc(100vh - 18rem)) scale(1); }
          75% { transform: translate(calc(-100vw + 18rem), 0) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-br {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(calc(-100vw + 18rem), 0) scale(1.1); }
          50% { transform: translate(calc(-100vw + 18rem), calc(-100vh + 18rem)) scale(1); }
          75% { transform: translate(0, calc(-100vh + 18rem)) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        @keyframes blob-bl {
          0% { transform: translate(0, 0) scale(1); }
          25% { transform: translate(0, calc(-100vh + 18rem)) scale(1.1); }
          50% { transform: translate(calc(100vw - 18rem), calc(-100vh + 18rem)) scale(1); }
          75% { transform: translate(calc(100vw - 18rem), 0) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
        
        .animate-blob-tl {
          animation: blob-tl 20s linear infinite;
        }
        
        .animate-blob-tr {
          animation: blob-tr 20s linear infinite;
        }
        
        .animate-blob-bl {
          animation: blob-bl 20s linear infinite;
        }
        
        .animate-blob-br {
          animation: blob-br 20s linear infinite;
        }
        
        .animate-pulse {
          animation: pulse 10s infinite;
        }
        
        @keyframes pulse {
          0%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0.5; }
          50% { transform: translate(-50%, -50%) scale(1.2); opacity: 0.3; }
        }
      `}</style>
      <Navigation currentPage="queue-game" />
    </div>
  );
};

export default QueueGame;