import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import About from './../Images/about.jpg';
import Bst from './../Images/bst.jpg';
import Hash from './../Images/hashing.jpg';
import Linkedlist from './../Images/ll.jpg';
import Stack from './../Images/stacks.jpg';
import Queue from './../Images/queue.jpg';
import Huffman from './../Images/huff.jpg';
import FeedbackForm from './Feedback';
import axios from 'axios';

const NavLink = ({ to, active, children }) => {
  return (
    <Link
      to={to}
      className={`font-sans px-4 py-2 rounded-lg transition-all duration-300 ${
        active 
          ? 'bg-blue-500 text-white hover:bg-blue-600' 
          : 'bg-white text-black hover:bg-blue-100'
      }`}
    >
      {children}
    </Link>
  );
};

const Card = ({ imgSrc, title, description, learnLink, playLink }) => {
  const navigate = useNavigate();
  
  return (
    <div className="relative w-[375px] h-[350px] group [perspective:1000px] font-sans">
      <div className="absolute w-full h-full transition-all duration-500 [transform-style:preserve-3d] group-hover:[transform:rotateY(180deg)]">
        <div className="absolute w-full h-full backface-hidden">
          <img src={imgSrc} alt={title} className="w-full h-full object-cover rounded-lg" />
          <h3 className="absolute bottom-0 w-full py-3 text-center text-white bg-black/40 font-bold">
            {title}
          </h3>
        </div>
        <div className="absolute w-full h-full overflow-hidden rounded-lg [transform:rotateY(180deg)] [backface-visibility:hidden] bg-[#054368] p-6 flex flex-col justify-between items-center">
          <h3 className="text-3xl font-bold text-white">{title}</h3>
          <p className="text-white/90 text-center">{description}</p>
          <div className="w-full space-y-4">
            <button 
              onClick={() => navigate(learnLink)}
              className="w-full py-3 rounded-full bg-[#bb66f8] text-white hover:bg-purple-600 transition-colors font-medium"
            >
              Learn
            </button>
            <button 
              onClick={() => navigate(playLink)}
              className="w-full py-3 rounded-full bg-[#bb66f8] text-white hover:bg-purple-600 transition-colors font-medium"
            >
              Play a game
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

const HomePage = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    const incrementVisitorCount = async () => {
      try {
        const response = await axios.post('https://script.google.com/macros/s/AKfycbw_9v9C0ECsySLSlLRLuXggvvIW2zFqYK5n7gWvYB_DChBCDtdah6Eohd8OoWZnulB0/exec');
        console.log('Visitor count updated:', response.data);
      } catch (error) {
        console.error('Error incrementing visitor count:', error);
      }
    };

    incrementVisitorCount();
  }, []);

  const cards = [
    {
      imgSrc: Queue,
      title: "Queue",
      description: "A queue is a linear data structure that follows the First-In-First-Out (FIFO) principle.",
      learnLink: "/queue",
      playLink: "/queuegame"
    },
    {
      imgSrc: Stack,
      title: "Stack",
      description: "A stack is a linear data structure that follows the Last-In-First-Out (LIFO) principle.",
      learnLink: "/stack",
      playLink: "/water"
    },
    {
      imgSrc: Linkedlist,
      title: "Linked List",
      description: "A linked list is a linear data structure consisting of nodes, each containing a value and a reference.",
      learnLink: "/linkedlist",
      playLink: "/ll-game"
    },
    {
      imgSrc: Bst,
      title: "Binary Search Tree",
      description: "A binary search tree (BST) arranges nodes so left children are smaller than their parents.",
      learnLink: "/bst",
      playLink: "/bstgame"
    },
    {
      imgSrc: Huffman,
      title: "Huffman Coding",
      description: "Huffman coding is a compression technique that assigns shorter codes to more frequent characters.",
      learnLink: "/huffman",
      playLink: "/huffmangame"
    },
    {
      imgSrc: Hash,
      title: "Hashing",
      description: "Hashing transforms input data into a fixed-size string of characters, typically serving as a unique identifier.",
      learnLink: "/hashlearn",
      playLink: "/hashing-game"
    }
  ];

  return (
    <div className="min-h-screen bg-white font-sans">
      <nav className="bg-[#000080] p-4 relative z-50">
        <div className="container mx-auto flex justify-between items-center">
          <Link to="/" className="text-2xl font-bold text-white">
            ALGORIFIC
          </Link>
          
          <div className="md:hidden">
            <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="text-white">
              {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>

          <div className={`${
            isMenuOpen ? 'flex' : 'hidden'
          } md:flex flex-col md:flex-row absolute md:relative top-full left-0 right-0 md:top-auto bg-[#000080] md:bg-transparent p-4 md:p-0 space-y-2 md:space-y-0 md:space-x-4 z-50`}>
            <NavLink to="/" active>Learn</NavLink>
            <NavLink to="/algohome">Algorithm</NavLink>
          </div>
        </div>
      </nav>

      <div className="container mx-auto px-4 py-16">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 justify-items-center">
          {cards.map((card, index) => (
            <Card key={index} {...card} />
          ))}
        </div>
      </div>

      <div className="bg-gray-50 py-16">
        <div className="container mx-auto px-4">
          <div className="flex flex-col md:flex-row items-center gap-10">
            <div className="w-full md:w-1/2">
              <img src={About} alt="About Us" className="rounded-lg w-full" />
            </div>
            <div className="w-full md:w-1/2">
              <p className="text-lg text-gray-800 text-justify">
                <strong>Algorific</strong> is dedicated to making Data Science
                accessible and engaging for all. Our mission is to simplify complex
                Data Science concepts through high-quality animated courses that
                transform learning into an enjoyable adventure.
              </p>
            </div>
          </div>
        </div>
      </div>

      <FeedbackForm />

      <footer className="bg-black text-white py-8">
        <div className="container mx-auto px-4">
          <h2 className="text-2xl font-bold text-center mb-6">Follow Us</h2>
          <div className="flex justify-center space-x-8">
            <a href="https://www.instagram.com" target="_blank" rel="noopener noreferrer" className="hover:text-blue-300 transition-colors">
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zm0-2.163c-3.259 0-3.667.014-4.947.072-4.358.2-6.78 2.618-6.98 6.98-.059 1.281-.073 1.689-.073 4.948 0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98 1.281.058 1.689.072 4.948.072 3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98-1.281-.059-1.69-.073-4.949-.073zm0 5.838c-3.403 0-6.162 2.759-6.162 6.162s2.759 6.163 6.162 6.163 6.162-2.759 6.162-6.163c0-3.403-2.759-6.162-6.162-6.162zm0 10.162c-2.209 0-4-1.79-4-4 0-2.209 1.791-4 4-4s4 1.791 4 4c0 2.21-1.791 4-4 4zm6.406-11.845c-.796 0-1.441.645-1.441 1.44s.645 1.44 1.441 1.44c.795 0 1.439-.645 1.439-1.44s-.644-1.44-1.439-1.44z"/></svg>
            </a>
            <a href="https://www.facebook.com" target="_blank" rel="noopener noreferrer" className="hover:text-blue-300 transition-colors">
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M9 8h-3v4h3v12h5v-12h3.642l.358-4h-4v-1.667c0-.955.192-1.333 1.115-1.333h2.885v-5h-3.808c-3.596 0-5.192 1.583-5.192 4.615v3.385z"/></svg>
            </a>
            <a href="https://www.linkedin.com" target="_blank" rel="noopener noreferrer" className="hover:text-blue-300 transition-colors">
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M4.98 3.5c0 1.381-1.11 2.5-2.48 2.5s-2.48-1.119-2.48-2.5c0-1.38 1.11-2.5 2.48-2.5s2.48 1.12 2.48 2.5zm.02 4.5h-5v16h5v-16zm7.982 0h-4.968v16h4.969v-8.399c0-4.67 6.029-5.052 6.029 0v8.399h4.988v-10.131c0-7.88-8.922-7.593-11.018-3.714v-2.155z"/></svg>
            </a>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default HomePage;