import React, { useState, useRef } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import Navigation from "../Navigation";

const QueueVisualization = () => {
  const [queue, setQueue] = useState([]);
  const [maxSize, setMaxSize] = useState(5);
  const [inputValue, setInputValue] = useState("");
  const [message, setMessage] = useState("");
  const [selectedLanguage, setSelectedLanguage] = useState("pseudo");
  const [activeSection, setActiveSection] = useState("learn");
  const [activeLearningPage, setActiveLearningPage] = useState(1);
  const [showHowToUseModal, setShowHowToUseModal] = useState(false);
  const inputRef = useRef(null);

  const HowToUseModal = () => (
    showHowToUseModal && (
      <div className="fixed inset-0 bg-black/50 flex justify-center items-center z-50 backdrop-blur-sm">
        <div className="bg-white p-6 rounded-2xl w-full max-w-md max-h-[600px] flex flex-col">
          <h2 className="text-2xl mb-4 text-indigo-900 text-center font-bold">
            How to Use Queue Visualization
          </h2>
          <div className="overflow-y-auto pr-3">
            <div className="space-y-3">
              {[
                "Enter a number between 1 and 999 in the input field.",
                "Click 'Enqueue' to add the number to the queue.",
                "Click 'Dequeue' to remove the first element from the queue.",
                "Adjust the queue size using the 'Queue Size' input if needed.",
                "Use 'Reset' to clear the entire queue."
              ].map((text, index) => (
                <div key={index} className="flex items-start gap-2.5">
                  <span className="min-w-6 h-6 bg-blue-100 text-indigo-900 rounded-full flex items-center justify-center font-bold">
                    {index + 1}
                  </span>
                  <p className="text-gray-700">{text}</p>
                </div>
              ))}
            </div>
            
            <div className="mt-4 p-3 bg-blue-50 rounded-lg">
              <h3 className="text-lg font-bold text-indigo-900 mb-2">Keyboard Shortcuts</h3>
              <ul className="space-y-2 text-gray-700">
                <li>• <strong>Enter</strong> - Enqueue number</li>
                <li>• <strong>Delete</strong> - Dequeue number</li>
                <li>• <strong>Esc</strong> - Close fullscreen</li>
              </ul>
            </div>
          </div>
          <button 
            onClick={() => setShowHowToUseModal(false)}
            className="w-full h-12 bg-indigo-900 text-white font-semibold rounded-lg mt-4 hover:bg-indigo-800"
          >
            Close
          </button>
        </div>
      </div>
    )
  );

  const handleInputChange = (e) => {
    const value = e.target.value.replace(/[^0-9]/g, '').slice(0, 3);
    setInputValue(value);
    setMessage("");
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') enqueue();
    else if (e.key === 'Delete') dequeue();
  };

  const handleSizeChange = (e) => {
    const newSize = parseInt(e.target.value);
    if (newSize >= 1 && newSize <= 100) {
      setMaxSize(newSize);
      setMessage(`Queue size updated to ${newSize}`);
    } else {
      setMessage("Queue size must be between 1 and 100");
    }
  };

  const enqueue = () => {
    const value = parseInt(inputValue);
    if (isNaN(value) || value < 1 || value > 999) {
      setMessage("Please enter a number between 1 and 999");
      return;
    }
    if (queue.length >= maxSize) {
      setMessage(`Queue is full. Maximum size is ${maxSize}`);
      return;
    }
    setQueue([...queue, value]);
    setInputValue("");
    setMessage(`${value} added to the queue`);
    inputRef.current?.focus();
  };

  const dequeue = () => {
    if (queue.length === 0) {
      setMessage("Queue is empty");
      return;
    }
    const removedItem = queue[0];
    setQueue(queue.slice(1));
    setMessage(`${removedItem} removed from the queue`);
  };

  const resetQueue = () => {
    setQueue([]);
    setMessage("Queue has been reset");
  };

  const togglePage = (direction) => {
    if (direction === 'next' && activeLearningPage < learningPages.length) {
      setActiveLearningPage(prev => prev + 1);
    } else if (direction === 'prev' && activeLearningPage > 1) {
      setActiveLearningPage(prev => prev - 1);
    }
  };

  const learningPages = [
    {
      content: (
        <div className="space-y-4 text-slate-700 flex flex-col justify-center items-center">
          <h2 className="flex text-2xl font-bold text-indigo-900 mb-6 justify-center">What is a Queue?</h2>
          <p style={{display:'flex', alignItems:'center', justifyContent:'center'}}>
            A queue is a linear data structure that follows the First-In-First-Out (FIFO) principle. 
            It's similar to a line of people waiting, where the first person to join is the first to be served.
          </p>

          <h3 className="text-xl font-bold text-indigo-800 mt-4">Key Terms</h3>
          <ul className="list-disc pl-6 space-y-2">
            <li><strong>Enqueue:</strong> Adding an element to the rear (end) of the queue</li>
            <li><strong>Dequeue:</strong> Removing an element from the front (start) of the queue</li>
            <li><strong>Front:</strong> The first element in the queue, ready to be removed</li>
            <li><strong>Rear:</strong> The last element in the queue, where new elements are added</li>
          </ul><br/>

          <div className="mt-6 bg-slate-100 rounded-xl p-4 flex justify-center items-center w-[80%]">
            <div className="flex flex-row gap-2">
              {["🍎", "🍐", "🍊"].map((fruit, index) => (
                <div 
                  key={index} 
                  className="w-12 h-12 bg-white border-2 border-indigo-300 rounded-lg flex items-center justify-center text-3xl"
                >
                  {fruit}
                </div>
              ))}
            </div>
            <div className="ml-4 text-slate-600 text-m font-semibold">
              <div>First In: 🍎</div>
              <div>First Out: 🍎</div>
            </div>
          </div>
        </div>
      )
    },
    {
      content: (
        <div className="space-y-4 text-slate-700 flex flex-col justify-center items-center">
          <h2 className="flex text-2xl font-bold text-indigo-900 mb-6 justify-center">Types and Applications</h2>
          <h3 className="text-xl font-bold text-indigo-800">Queue Variations</h3>
          <ul className="list-disc pl-6 space-y-2">
            <li><strong>Simple Queue:</strong> Basic FIFO implementation</li>
            <li><strong>Circular Queue:</strong> Connects rear to front for space efficiency</li>
            <li><strong>Priority Queue:</strong> Elements dequeued based on priority</li>
            <li><strong>Double-Ended Queue:</strong> Insertion/deletion from both ends</li>
          </ul>

          <h3 className="text-xl font-bold text-indigo-800 mt-6">Real-world Applications</h3>
          <ul className="list-disc pl-6 space-y-2">
            <li><strong>Process Scheduling:</strong> Managing CPU tasks</li>
            <li><strong>Print Spooling:</strong> Managing print jobs</li>
            <li><strong>Web Servers:</strong> Handling client requests</li>
            <li><strong>Customer Service:</strong> Managing support tickets</li>
          </ul>
        </div>
      )
    }
  ];
  
  const codeExamples = {
    pseudo: `Queue Operations Pseudocode:

enqueue(element):
    if queue is full:
        return overflow
    increment rear
    queue[rear] = element
    return success

dequeue():
    if queue is empty:
        return underflow
    element = queue[front]
    increment front
    return element`,

    cpp: `<span class="text-pink-500">template</span> <span class="text-purple-400">&lt;</span><span class="text-pink-500">typename</span> <span class="text-green-400">T</span><span class="text-purple-400">&gt;</span>
<span class="text-pink-500">class</span> <span class="text-green-400">Queue</span> {
<span class="text-pink-500">private</span>:
    <span class="text-green-400">T</span>* arr;
    <span class="text-pink-500">int</span> front, rear, size;
    
<span class="text-pink-500">public</span>:
    <span class="text-green-400">Queue</span>(<span class="text-pink-500">int</span> s) {
        front = rear = -<span class="text-purple-400">1</span>;
        size = s;
        arr = <span class="text-pink-500">new</span> <span class="text-green-400">T</span>[s];
    }
    
    <span class="text-pink-500">void</span> <span class="text-green-400">enqueue</span>(<span class="text-green-400">T</span> x) {
        <span class="text-pink-500">if</span> (rear == size-<span class="text-purple-400">1</span>) 
            <span class="text-pink-500">return</span>;
            
        <span class="text-pink-500">if</span> (front == -<span class="text-purple-400">1</span>) 
            front = <span class="text-purple-400">0</span>;
            
        arr[++rear] = x;
    }
    
    <span class="text-green-400">T</span> <span class="text-green-400">dequeue</span>() {
        <span class="text-pink-500">if</span> (front == -<span class="text-purple-400">1</span>) 
            <span class="text-pink-500">return</span> <span class="text-green-400">T</span>();
            
        <span class="text-green-400">T</span> x = arr[front];
        
        <span class="text-pink-500">if</span> (front == rear)
            front = rear = -<span class="text-purple-400">1</span>;
        <span class="text-pink-500">else</span>
            front++;
            
        <span class="text-pink-500">return</span> x;
    }
};`,

    java: `<span class="text-pink-500">class</span> <span class="text-green-400">Queue</span><span class="text-purple-400">&lt;</span><span class="text-green-400">T</span><span class="text-purple-400">&gt;</span> {
    <span class="text-pink-500">private</span> <span class="text-green-400">T</span>[] arr;
    <span class="text-pink-500">private</span> <span class="text-pink-500">int</span> front, rear, size;
    
    <span class="text-green-400">Queue</span>(<span class="text-pink-500">int</span> s) {
        front = rear = -<span class="text-purple-400">1</span>;
        size = s;
        arr = (<span class="text-green-400">T</span>[]) <span class="text-pink-500">new</span> <span class="text-green-400">Object</span>[s];
    }
    
    <span class="text-pink-500">void</span> <span class="text-green-400">enqueue</span>(<span class="text-green-400">T</span> x) {
        <span class="text-pink-500">if</span> (rear == size-<span class="text-purple-400">1</span>) 
            <span class="text-pink-500">return</span>;
            
        <span class="text-pink-500">if</span> (front == -<span class="text-purple-400">1</span>) 
            front = <span class="text-purple-400">0</span>;
            
        arr[++rear] = x;
    }
    
    <span class="text-green-400">T</span> <span class="text-green-400">dequeue</span>() {
        <span class="text-pink-500">if</span> (front == -<span class="text-purple-400">1</span>) 
            <span class="text-pink-500">return</span> <span class="text-pink-500">null</span>;
            
        <span class="text-green-400">T</span> x = arr[front];
        
        <span class="text-pink-500">if</span> (front == rear)
            front = rear = -<span class="text-purple-400">1</span>;
        <span class="text-pink-500">else</span>
            front++;
            
        <span class="text-pink-500">return</span> x;
    }
}`,

    c: `<span class="text-pink-500">#define</span> <span class="text-green-400">MAX_SIZE</span> <span class="text-purple-400">100</span>

<span class="text-pink-500">typedef</span> <span class="text-pink-500">struct</span> {
    <span class="text-pink-500">int</span> items[<span class="text-green-400">MAX_SIZE</span>];
    <span class="text-pink-500">int</span> front;
    <span class="text-pink-500">int</span> rear;
    <span class="text-pink-500">int</span> size;
} <span class="text-green-400">Queue</span>;

<span class="text-pink-500">void</span> <span class="text-green-400">initQueue</span>(<span class="text-green-400">Queue</span>* q, <span class="text-pink-500">int</span> s) {
    q->front = -<span class="text-purple-400">1</span>;
    q->rear = -<span class="text-purple-400">1</span>;
    q->size = s;
}

<span class="text-pink-500">int</span> <span class="text-green-400">isEmpty</span>(<span class="text-green-400">Queue</span>* q) {
    <span class="text-pink-500">return</span> q->front == -<span class="text-purple-400">1</span>;
}

<span class="text-pink-500">int</span> <span class="text-green-400">isFull</span>(<span class="text-green-400">Queue</span>* q) {
    <span class="text-pink-500">return</span> q->rear == q->size - <span class="text-purple-400">1</span>;
}

<span class="text-pink-500">void</span> <span class="text-green-400">enqueue</span>(<span class="text-green-400">Queue</span>* q, <span class="text-pink-500">int</span> value) {
    <span class="text-pink-500">if</span> (isFull(q)) {
        <span class="text-pink-500">return</span>;
    }
    
    <span class="text-pink-500">if</span> (isEmpty(q)) {
        q->front = <span class="text-purple-400">0</span>;
    }
    
    q->items[++q->rear] = value;
}

<span class="text-pink-500">int</span> <span class="text-green-400">dequeue</span>(<span class="text-green-400">Queue</span>* q) {
    <span class="text-pink-500">if</span> (isEmpty(q)) {
        <span class="text-pink-500">return</span> -<span class="text-purple-400">1</span>;
    }
    
    <span class="text-pink-500">int</span> value = q->items[q->front];
    
    <span class="text-pink-500">if</span> (q->front == q->rear) {
        q->front = q->rear = -<span class="text-purple-400">1</span>;
    } <span class="text-pink-500">else</span> {
        q->front++;
    }
    
    <span class="text-pink-500">return</span> value;
}`,

    python: `<span class="text-pink-500">class</span> <span class="text-green-400">Queue</span>:
    <span class="text-pink-500">def</span> <span class="text-green-400">__init__</span>(<span class="text-gray-200">self</span>, <span class="text-gray-200">size</span>):
        <span class="text-gray-200">self</span>.size = size
        <span class="text-gray-200">self</span>.queue = []
        
    <span class="text-pink-500">def</span> <span class="text-green-400">enqueue</span>(<span class="text-gray-200">self</span>, <span class="text-gray-200">item</span>):
        <span class="text-pink-500">if</span> <span class="text-gray-200">len</span>(<span class="text-gray-200">self</span>.queue) >= <span class="text-gray-200">self</span>.size:
            <span class="text-pink-500">return</span> <span class="text-pink-500">None</span>
            
        <span class="text-gray-200">self</span>.queue.append(item)
        
    <span class="text-pink-500">def</span> <span class="text-green-400">dequeue</span>(<span class="text-gray-200">self</span>):
        <span class="text-pink-500">if</span> <span class="text-gray-200">len</span>(<span class="text-gray-200">self</span>.queue) < <span class="text-purple-400">1</span>:
            <span class="text-pink-500">return</span> <span class="text-pink-500">None</span>
            
        <span class="text-pink-500">return</span> <span class="text-gray-200">self</span>.queue.pop(<span class="text-purple-400">0</span>)
        
    <span class="text-pink-500">def</span> <span class="text-green-400">display</span>(<span class="text-gray-200">self</span>):
        <span class="text-pink-500">return</span> <span class="text-gray-200">self</span>.queue`,
  };

  const renderContent = () => {
    switch (activeSection) {
      case "learn":
        return renderLearningContent();
      case "visualization":
        return renderVisualizationContent();
      case "implementation":
        return renderImplementationContent();
      default:
        return null;
    }
  };

  const renderLearningContent = () => {
    const currentPage = learningPages[activeLearningPage - 1];
    return (
      <div className="flex-grow p-4 flex flex-col overflow-y-auto">
        <div className="flex-grow">
          <h3 className="text-2xl font-bold text-indigo-800 mb-4">
            {currentPage.title}
          </h3>
          {currentPage.content}
        </div>
        
        <div className="flex justify-center items-center gap-4 mt-6">
          <button 
            onClick={() => togglePage('prev')} 
            disabled={activeLearningPage === 1}
            className={`p-2 rounded-full ${activeLearningPage === 1 ? 'bg-slate-200' : 'bg-indigo-100 hover:bg-indigo-200'}`}
          >
            <ChevronLeft className={`w-6 h-6 ${activeLearningPage === 1 ? 'text-slate-400' : 'text-indigo-800'}`} />
          </button>
          <span className="text-slate-600">
            Page {activeLearningPage} of {learningPages.length}
          </span>
          <button 
            onClick={() => togglePage('next')} 
            disabled={activeLearningPage === learningPages.length}
            className={`p-2 rounded-full ${activeLearningPage === learningPages.length ? 'bg-slate-200' : 'bg-indigo-100 hover:bg-indigo-200'}`}
          >
            <ChevronRight className={`w-6 h-6 ${activeLearningPage === learningPages.length ? 'text-slate-400' : 'text-indigo-800'}`} />
          </button>
        </div>
      </div>
    );
  };

  const renderVisualizationContent = () => (
    <div className="flex-grow p-4 overflow-y-auto">
      <div className="flex justify-center items-center gap-4">
        <h1 className="text-xl md:text-3xl font-bold bg-gradient-to-r from-indigo-900 to-indigo-600 bg-clip-text text-transparent">
          Queue Visualization
        </h1>
        <button 
          className="text-xl md:text-2xl text-indigo-900 hover:bg-indigo-100 rounded p-1"
          onClick={() => setShowHowToUseModal(true)}
        >
          ℹ️
        </button>
      </div>

      <div className="bg-slate-50 rounded-xl p-6 border-2 border-slate-200 shadow-inner mb-6 h-60 mt-4">
        <div className="w-full h-full overflow-x-auto">
          <div className="flex flex-row items-center gap-4 h-full min-w-max">
            {queue.length === 0 ? (
              <p className="text-slate-400 italic w-full text-center">
                Queue is empty
              </p>
            ) : (
              queue.map((item, index) => (
                <div 
                  key={index}
                  className="relative min-w-[100px] h-20 flex items-center justify-center text-white text-2xl font-bold rounded-xl shadow-md"
                  style={{ backgroundColor: `hsl(${200 + index * 15}, 75%, 65%)` }}
                >
                  {item}
                  {index === 0 && (
                    <span className="absolute -bottom-6 left-1/2 -translate-x-1/2 text-xs text-slate-600 font-medium">
                      Front
                    </span>
                  )}
                  {index === queue.length - 1 && (
                    <span className="absolute -top-6 left-1/2 -translate-x-1/2 text-xs text-slate-600 font-medium">
                      Rear
                    </span>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>

      <div className="flex items-center gap-3 mb-4 justify-center">
        <label className="text-slate-600 font-medium">Queue Size:</label>
        <input 
          type="number"
          min="1"
          max="100"
          value={maxSize}
          onChange={handleSizeChange}
          className="w-20 p-2 rounded-lg border-2 border-slate-300 text-center"
        />
      </div>

      <div className="space-y-4 px-4">
        <div className="flex flex-col md:flex-row gap-4">
          <input
            type="text"
            value={inputValue}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            ref={inputRef}
            placeholder="Enter value (1-999)"
            className="flex-1 p-3.5 rounded-lg border-2 border-slate-300"
          />
          <button
            onClick={enqueue}
            className="md:w-32 px-7 py-3.5 rounded-lg text-white font-semibold bg-blue-500 hover:bg-blue-600 transition-colors"
          >
            Enqueue
          </button>
        </div>
        
        <div className="flex justify-center gap-4">
          <button
            onClick={dequeue}
            className="px-7 py-3.5 rounded-lg text-white font-semibold bg-emerald-500 hover:bg-emerald-600 transition-colors w-32"
          >
            Dequeue
          </button>
          <button
            onClick={resetQueue}
            className="px-7 py-3.5 rounded-lg text-white font-semibold bg-red-500 hover:bg-red-600 transition-colors w-32"
          >
            Reset
          </button>
        </div>
      </div>

      {message && (
        <div className={`mt-5 p-3.5 rounded-lg font-semibold text-center
          ${message.includes("between") || message.includes("full") || message.includes("empty")
            ? "bg-red-100 text-red-600"
            : "bg-green-100 text-green-600"
          }`}
        >
          {message}
        </div>
      )}
    </div>
  );

  const renderImplementationContent = () => (
    <div className="flex-grow p-4 overflow-y-auto">
      <h2 className="text-2xl md:text-3xl font-bold bg-gradient-to-r from-indigo-900 to-indigo-600 bg-clip-text text-transparent text-center mb-4">
        Implementation
      </h2>

      <select
        value={selectedLanguage}
        onChange={(e) => setSelectedLanguage(e.target.value)}
        className="w-full p-3 rounded-lg border-2 border-slate-200 mb-4"
      >
        <option value="pseudo">Pseudocode</option>
        <option value="cpp">C++</option>
        <option value="c">C</option>
        <option value="python">Python</option>
        <option value="java">Java</option>
      </select>

      <pre className="bg-gray-900 text-white p-5 overflow-auto rounded-2xl leading-relaxed">
        <code dangerouslySetInnerHTML={{ __html: codeExamples[selectedLanguage] }} />
      </pre>
      <div className="mt-6 p-4 bg-blue-50 rounded-lg border border-blue-100">
      <h3 className="text-lg font-bold text-indigo-900 mb-2">
        Implementation Notes
      </h3>
      <ul className="space-y-2 text-gray-700">
        <li className="flex items-start gap-2">
          <span className="text-indigo-500">•</span>
          <strong>Time Complexity:</strong> O(1) for both enqueue and dequeue operations
        </li>
        <li className="flex items-start gap-2">
          <span className="text-indigo-500">•</span>
          <strong>Space Complexity:</strong> O(n) where n is the number of elements
        </li>
        <li className="flex items-start gap-2">
          <span className="text-indigo-500">•</span>
          <strong>Best used when:</strong> First-in-first-out (FIFO) ordering is required, like in: <br/>
          • Task scheduling<br/>
          • Print queue management<br/>
          • Breadth-first search algorithms
        </li>
      </ul>
    </div>
    </div>
  );

  return (
    <div className="flex flex-col w-full gap-6 p-4 bg-gradient-to-br from-blue-50 to-blue-100 min-h-screen">
      <div className={`relative w-full transition-all duration-300 ease-in-out h-[700px]
        bg-white rounded-2xl shadow-lg p-0 flex flex-col`}>
        
        <div className="flex p-0 justify-around items-center border-b-2 h-[8vh] z-50">
          <div 
            onClick={() => setActiveSection("learn")}
            className={`w-1/3 text-center border-r-2 h-[50px] flex items-center justify-center cursor-pointer 
              ${activeSection === "learn" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Learn
          </div>
          
          <div 
            onClick={() => setActiveSection("visualization")}
            className={`w-1/3 text-center border-r-2 h-[50px] flex items-center justify-center cursor-pointer
              ${activeSection === "visualization" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Visualize
          </div>

          <div 
            onClick={() => setActiveSection("implementation")}
            className={`w-1/3 text-center h-[50px] flex items-center justify-center cursor-pointer
              ${activeSection === "implementation" ? 'bg-blue-100 font-bold' : 'hover:bg-blue-50'}`}
          >
            Code
          </div>
        </div>

        {renderContent()}
      </div>
      
      <Navigation currentPage="queue-learn" />
      {HowToUseModal()}
    </div>
  );
};

export default QueueVisualization;